    let audioCtx = null;
    let audioMaster = null;
    let musicBus = null;
    let sfxBus = null;
    let ambienceBus = null;
    let musicStarted = false;
    let musicMuted = false;
    let sfxDecodeStarted = false;
    let sfxDecodeReady = false;
    const sfxBuffers = {};
    const sfxCooldowns = {};
    let p1WasGroundedForSfx = true;
    let p2WasGroundedForSfx = true;
    let p1StepTimer = 0;
    let p2StepTimer = 0;

    let mp3Tracks = [];
    let mp3TrackBuffers = [];
    let mp3TrackSources = [];
    let mp3TrackGains = [];
    let menuMusicBuffer = null;
    let menuMusicSource = null;
    let menuMusicGain = null;
    let mp3DecodeStarted = false;
    let mp3DecodeReady = false;
    let currentMp3Index = -1;
    let pendingMp3Index = 0;
    let mp3FadeTimer = 0;
    const MP3_STAGE_VOLUME = 0.72; // base, final volume controlled by musicVolume
    const MP3_FADE_SECONDS = 2.2;
    let ambienceSourcesReady = false;
    const ambienceSources = {};
    const ambienceTimers = {
      forestBird: 0,
      forestLeaves: 0,
      loggingCreak: 0,
      loggingThud: 0,
      cinderPop: 0,
      cinderHiss: 0,
      mysticLeaves: 0,
      mysticBell: 0
    };

    let runMusicSeed = Math.floor(Math.random() * 999999);
    let musicRngState = runMusicSeed || 1;
    let forestComposition = null;
    let loggingComposition = null;
    let cinderComposition = null;
    let mysticComposition = null;
    let musicNextStepTime = 0;
    let musicStep = 0;
    const MUSIC_BPM = 78;
    const MUSIC_STEP = 60 / MUSIC_BPM / 2; // eighth notes

    function seededRand() {
      // Small deterministic LCG so a seed can recreate the same melody later.
      musicRngState = (musicRngState * 1664525 + 1013904223) >>> 0;
      return musicRngState / 4294967296;
    }

    function seededChoice(arr) {
      return arr[Math.floor(seededRand() * arr.length)];
    }

    function reseedForestMusic(seed = Math.floor(Math.random() * 999999)) {
      runMusicSeed = seed;
      musicRngState = seed || 1;
      forestComposition = generateForestComposition();

      // Same run seed, second generated identity.
      // The RNG state continues forward, so the Logging Pass is related to the
      // Forest tune, but still has its own rhythm/melody.
      loggingComposition = generateLoggingComposition();
      cinderComposition = generateCinderComposition();
      mysticComposition = generateMysticComposition();

      musicStep = 0;
      if (audioCtx) musicNextStepTime = audioCtx.currentTime + 0.08;
    }

    function generateForestComposition() {
      // Think "black keys on a keyboard": safe pentatonic notes, but arranged
      // into a gentle Japanese folk-style travelling tune.
      const roots = [196, 207.65, 220, 246.94]; // G3, Ab3, A3, B3-ish options
      const root = seededChoice(roots);
      const scale = [0, 2, 5, 7, 9, 12, 14, 17, 19]; // soft pentatonic palette

      const phrase = [];
      let idx = Math.floor(seededRand() * 4) + 1;
      for (let i = 0; i < 32; i++) {
        // Gentle random walk, not chaotic random notes.
        if (i % 8 === 0) idx = seededChoice([1, 2, 3, 4]);
        else idx += seededChoice([-1, 0, 0, 1]);
        idx = Math.max(0, Math.min(scale.length - 1, idx));

        // Breath marks leave space so it feels like a song, not a machine gun.
        const rest = (i % 8 === 6 && seededRand() < 0.65) || (i % 16 === 14 && seededRand() < 0.85);
        const long = (i % 8 === 0 || i % 8 === 4);
        phrase.push({
          note: scale[idx] + seededChoice([0, 0, 0, 12]),
          rest,
          length: long ? 2 : seededChoice([1, 1, 2])
        });
      }

      const bassPattern = [0, -5, -3, -5, 0, -7, -5, -3].map(n => n + seededChoice([0, 0, -12]));
      const chimeSteps = [];
      for (let i = 0; i < 32; i++) {
        if (seededRand() < 0.14) chimeSteps.push(i);
      }

      return {
        root,
        phrase,
        bassPattern,
        chimeSteps,
        woodDensity: 0.42 + seededRand() * 0.16,
        melodyWave: seededChoice(["triangle", "sine", "square"])
      };
    }

    function generateLoggingComposition() {
      // Logging Pass: same seed-family, but heavier and more drum-led.
      // Think distant taiko/woodblock pulse with a darker travelling motif.
      const roots = [130.81, 146.83, 164.81, 174.61]; // lower register
      const root = seededChoice(roots);
      const scale = [0, 2, 5, 7, 9, 12, 14];

      const motif = [];
      let idx = seededChoice([0, 1, 2, 3]);
      for (let i = 0; i < 16; i++) {
        if (i % 4 === 0) idx = seededChoice([0, 1, 2]);
        else idx += seededChoice([-1, 0, 1, 1]);
        idx = Math.max(0, Math.min(scale.length - 1, idx));

        motif.push({
          note: scale[idx] + seededChoice([0, 0, 12]),
          hit: seededRand() > 0.28,
          accent: i % 8 === 0 || i % 8 === 5
        });
      }

      const drumPattern = [];
      for (let i = 0; i < 16; i++) {
        // 0 silent, 1 wood, 2 deep drum, 3 accent drum
        let v = 0;
        if (i % 8 === 0) v = 3;
        else if (i % 4 === 2) v = 2;
        else if (i % 2 === 0 && seededRand() < 0.75) v = 1;
        else if (seededRand() < 0.18) v = 1;
        drumPattern.push(v);
      }

      const bassPattern = [0, -5, 0, -7, -3, -5, 0, -10].map(n => n + seededChoice([0, 0, -12]));

      return {
        root,
        motif,
        drumPattern,
        bassPattern,
        pulse: 0.78 + seededRand() * 0.18,
        melodyWave: seededChoice(["square", "triangle"])
      };
    }

    function generateCinderComposition() {
      // Cinder Path: faster, darker, more ominous.
      // Same run seed family, but now the melody is tighter and the bass is deeper.
      const roots = [98, 110, 116.54, 130.81]; // deep G2/A2/Bb2/C3 area
      const root = seededChoice(roots);
      const scale = [0, 1, 5, 6, 7, 10, 12, 13]; // darker flavour than forest/logging

      const motif = [];
      let idx = seededChoice([0, 1, 2, 3]);
      for (let i = 0; i < 32; i++) {
        if (i % 8 === 0) idx = seededChoice([0, 1, 2]);
        else idx += seededChoice([-1, 0, 1, 1, 2]);
        idx = Math.max(0, Math.min(scale.length - 1, idx));

        motif.push({
          note: scale[idx] + seededChoice([0, 0, 12]),
          hit: seededRand() > 0.34,
          stab: i % 8 === 3 || i % 8 === 7
        });
      }

      const drumPattern = [];
      for (let i = 0; i < 32; i++) {
        // 0 silent, 1 ember tick, 2 deep pulse, 3 heavy hit
        let v = 0;
        if (i % 8 === 0) v = 3;
        else if (i % 4 === 2) v = 2;
        else if (i % 2 === 1 && seededRand() < 0.52) v = 1;
        else if (seededRand() < 0.22) v = 1;
        drumPattern.push(v);
      }

      const bassPattern = [0, -12, -5, -12, -6, -12, -3, -15].map(n => n + seededChoice([0, -12]));
      const dangerTone = seededChoice([6, 10, 13, 18]);

      return {
        root,
        motif,
        drumPattern,
        bassPattern,
        dangerTone,
        pulse: 0.92 + seededRand() * 0.18,
        melodyWave: seededChoice(["sawtooth", "square"])
      };
    }

    function generateMysticComposition() {
      // Mystic Sakura Forest: meditative, beautiful, spacious.
      // Same seed family again, but it opens up into bells, breath, and slow phrases.
      const roots = [174.61, 196, 220, 246.94]; // F/G/A/B area, warmer and higher than Cinder
      const root = seededChoice(roots);

      // Softer pentatonic colour with a few suspended-feeling steps.
      const scale = [0, 2, 5, 7, 9, 12, 14, 17, 19, 21];

      const phrase = [];
      let idx = seededChoice([2, 3, 4, 5]);
      for (let i = 0; i < 48; i++) {
        // Slow wandering melody with lots of breath.
        if (i % 12 === 0) idx = seededChoice([2, 3, 4]);
        else idx += seededChoice([-1, 0, 0, 1]);
        idx = Math.max(0, Math.min(scale.length - 1, idx));

        const rest = (i % 6 === 4 && seededRand() < 0.72) || (i % 12 === 10 && seededRand() < 0.86);
        const length = seededChoice([2, 2, 3, 4]);

        phrase.push({
          note: scale[idx] + seededChoice([0, 0, 12]),
          rest,
          length,
          bell: seededRand() < 0.22
        });
      }

      const bassPattern = [0, -5, -7, -5, -3, -5, 0, -12].map(n => n + seededChoice([0, 0, -12]));
      const bellSteps = [];
      for (let i = 0; i < 48; i++) {
        if (i % 12 === 2 || (seededRand() < 0.10 && i % 2 === 0)) bellSteps.push(i);
      }

      return {
        root,
        phrase,
        bassPattern,
        bellSteps,
        breathDensity: 0.32 + seededRand() * 0.18,
        shimmerTone: seededChoice([19, 21, 24, 26, 29]),
        melodyWave: seededChoice(["sine", "triangle"])
      };
    }

    function musicFreq(semitone) {
      const comp = forestComposition || generateForestComposition();
      return comp.root * Math.pow(2, semitone / 12);
    }

    function ensureAudioStarted() {
      if (musicMuted) return;

      if (!audioCtx) {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        if (!AudioContextClass) return;
        audioCtx = new AudioContextClass();

        audioMaster = audioCtx.createGain();
        audioMaster.gain.value = 0.92;
        audioMaster.connect(audioCtx.destination);

        musicBus = audioCtx.createGain();
        musicBus.gain.value = 1.0;
        musicBus.connect(audioMaster);

        sfxBus = audioCtx.createGain();
        sfxBus.gain.value = sfxVolume;
        sfxBus.connect(audioMaster);
      }

      if (audioCtx.state === "suspended") audioCtx.resume();
      ensureSfxDecoded();
      ensureMp3SoundtrackStarted();
    }

    function makeEnvelope(start, peak, attack, decay, sustain, release, duration) {
      const g = audioCtx.createGain();
      g.gain.setValueAtTime(0.0001, start);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), start + attack);
      g.gain.exponentialRampToValueAtTime(Math.max(0.0002, sustain), start + attack + decay);
      g.gain.setValueAtTime(Math.max(0.0002, sustain), start + Math.max(attack + decay, duration - release));
      g.gain.exponentialRampToValueAtTime(0.0001, start + duration);
      return g;
    }

    function playPluckedTone(freq, start, duration, peak = 0.035, wave = "triangle", filterHz = 1450) {
      if (!audioCtx || !musicBus) return;

      const osc = audioCtx.createOscillator();
      const filter = audioCtx.createBiquadFilter();
      const g = makeEnvelope(start, peak, 0.012, 0.080, peak * 0.18, 0.120, duration);

      osc.type = wave;
      osc.frequency.setValueAtTime(freq, start);

      filter.type = "lowpass";
      filter.frequency.setValueAtTime(filterHz, start);
      filter.Q.value = 0.45;

      osc.connect(filter);
      filter.connect(g);
      g.connect(musicBus);

      osc.start(start);
      osc.stop(start + duration + 0.05);
    }

    function playSoftWood(start, peak = 0.014) {
      if (!audioCtx || !musicBus) return;
      const duration = 0.038;
      const bufferSize = Math.floor(audioCtx.sampleRate * duration);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 2);

      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = "bandpass";
      filter.frequency.value = 820;
      filter.Q.value = 1.8;
      const g = makeEnvelope(start, peak, 0.004, 0.018, peak * 0.16, 0.025, duration);

      src.connect(filter);
      filter.connect(g);
      g.connect(musicBus);
      src.start(start);
      src.stop(start + duration + 0.03);
    }

    function playDeepDrum(start, peak = 0.060, accent = false) {
      if (!audioCtx || !musicBus) return;

      const osc = audioCtx.createOscillator();
      const g = makeEnvelope(start, peak, 0.004, 0.050, peak * 0.18, 0.170, accent ? 0.34 : 0.24);
      osc.type = "sine";
      osc.frequency.setValueAtTime(accent ? 92 : 76, start);
      osc.frequency.exponentialRampToValueAtTime(accent ? 43 : 38, start + (accent ? 0.24 : 0.18));
      osc.connect(g);
      g.connect(musicBus);
      osc.start(start);
      osc.stop(start + (accent ? 0.38 : 0.28));

      // Soft noisy skin transient.
      const bufferSize = Math.floor(audioCtx.sampleRate * 0.045);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 3);

      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = "lowpass";
      filter.frequency.value = accent ? 520 : 380;
      const ng = makeEnvelope(start, peak * 0.28, 0.002, 0.014, peak * 0.06, 0.020, 0.055);
      src.connect(filter);
      filter.connect(ng);
      ng.connect(musicBus);
      src.start(start);
      src.stop(start + 0.065);
    }

    function playEmberTick(start, peak = 0.012) {
      if (!audioCtx || !musicBus) return;

      const duration = 0.030;
      const bufferSize = Math.floor(audioCtx.sampleRate * duration);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 5);
      }

      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = "highpass";
      filter.frequency.value = 1700;
      filter.Q.value = 0.7;
      const g = makeEnvelope(start, peak, 0.002, 0.012, peak * 0.12, 0.018, duration);

      src.connect(filter);
      filter.connect(g);
      g.connect(musicBus);
      src.start(start);
      src.stop(start + duration + 0.02);
    }

    function playMysticBreath(start, peak = 0.010) {
      if (!audioCtx || !musicBus) return;

      const duration = 0.46;
      const bufferSize = Math.floor(audioCtx.sampleRate * duration);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const env = Math.sin(Math.PI * (i / bufferSize));
        data[i] = (Math.random() * 2 - 1) * env * 0.38;
      }

      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = "bandpass";
      filter.frequency.value = 1350;
      filter.Q.value = 0.55;
      const g = makeEnvelope(start, peak, 0.080, 0.120, peak * 0.52, 0.220, duration);

      src.connect(filter);
      filter.connect(g);
      g.connect(musicBus);
      src.start(start);
      src.stop(start + duration + 0.04);
    }

    function playBellTone(freq, start, duration, peak = 0.020) {
      if (!audioCtx || !musicBus) return;

      const osc1 = audioCtx.createOscillator();
      const osc2 = audioCtx.createOscillator();
      const g = makeEnvelope(start, peak, 0.014, 0.220, peak * 0.20, 0.520, duration);

      osc1.type = "sine";
      osc2.type = "triangle";
      osc1.frequency.setValueAtTime(freq, start);
      osc2.frequency.setValueAtTime(freq * 2.01, start);

      const g2 = audioCtx.createGain();
      g2.gain.value = 0.24;

      osc1.connect(g);
      osc2.connect(g2);
      g2.connect(g);
      g.connect(musicBus);

      osc1.start(start);
      osc2.start(start);
      osc1.stop(start + duration + 0.08);
      osc2.stop(start + duration + 0.08);
    }

    function scheduleForestStep(time) {
      const comp = forestComposition || generateForestComposition();
      const step = musicStep % 32;
      const phraseNote = comp.phrase[step];

      // Gentle travelling pulse, fixed to the music clock only.
      if (step % 2 === 0 && Math.random() < comp.woodDensity) playSoftWood(time, 0.012);
      if (step % 8 === 4) playSoftWood(time + 0.012, 0.018);

      // Bass breath every two beats.
      if (step % 4 === 0) {
        const bass = comp.bassPattern[Math.floor(step / 4) % comp.bassPattern.length];
        playPluckedTone(musicFreq(bass - 12), time, MUSIC_STEP * 3.4, 0.022, "triangle", 720);
      }

      // Melody on alternate eighths with space and longer phrase notes.
      if (!phraseNote.rest && step % 2 === 0) {
        const dur = MUSIC_STEP * phraseNote.length * 1.35;
        playPluckedTone(
          musicFreq(phraseNote.note + 12),
          time + 0.018,
          dur,
          0.028,
          comp.melodyWave,
          1680
        );
      }

      // Occasional high forest sparkle.
      if (comp.chimeSteps.includes(step)) {
        playPluckedTone(musicFreq(phraseNote.note + 24), time + MUSIC_STEP * 0.72, MUSIC_STEP * 2.2, 0.012, "sine", 2300);
      }

      musicStep++;
      musicNextStepTime += MUSIC_STEP;
    }

    function scheduleLoggingStep(time) {
      const comp = loggingComposition || generateLoggingComposition();
      const step = musicStep % 32;
      const halfStep = step % 16;

      // Drum-led pulse. Heavier than forest, but still procedural and seeded.
      const drum = comp.drumPattern[halfStep];
      if (drum === 1) playSoftWood(time, 0.017 * comp.pulse);
      else if (drum === 2) playDeepDrum(time, 0.045 * comp.pulse, false);
      else if (drum === 3) playDeepDrum(time, 0.075 * comp.pulse, true);

      // Bassy heartbeat every two beats.
      if (step % 4 === 0) {
        const bass = comp.bassPattern[Math.floor(step / 4) % comp.bassPattern.length];
        playPluckedTone(musicFreqLogging(bass - 12), time + 0.006, MUSIC_STEP * 3.8, 0.032, "triangle", 540);
      }

      // Shorter, lower motif than forest. Feels like marching through cut timber.
      const motif = comp.motif[halfStep];
      if (motif.hit && step % 2 === 0) {
        playPluckedTone(
          musicFreqLogging(motif.note + 12),
          time + 0.025,
          MUSIC_STEP * (motif.accent ? 1.8 : 1.15),
          motif.accent ? 0.032 : 0.023,
          comp.melodyWave,
          1180
        );
      }

      // Occasional ominous high knock, like echoing timber.
      if (halfStep === 11 && comp.pulse > 0.84) {
        playPluckedTone(musicFreqLogging(24), time + MUSIC_STEP * 0.55, MUSIC_STEP * 1.5, 0.010, "sine", 1800);
      }

      musicStep++;
      musicNextStepTime += MUSIC_STEP;
    }

    function musicFreqLogging(semitone) {
      const comp = loggingComposition || generateLoggingComposition();
      return comp.root * Math.pow(2, semitone / 12);
    }

    function scheduleCinderStep(time) {
      const comp = cinderComposition || generateCinderComposition();
      const step = musicStep % 32;

      // Cinder feels faster by subdividing extra hits inside the same global clock.
      const drum = comp.drumPattern[step];
      if (drum === 1) playEmberTick(time, 0.012 * comp.pulse);
      else if (drum === 2) playDeepDrum(time, 0.052 * comp.pulse, false);
      else if (drum === 3) playDeepDrum(time, 0.088 * comp.pulse, true);

      // Off-beat ember tick for urgency.
      if (step % 2 === 0) playEmberTick(time + MUSIC_STEP * 0.52, 0.007);

      // Deep, ominous bass drone/pulse.
      if (step % 4 === 0) {
        const bass = comp.bassPattern[Math.floor(step / 4) % comp.bassPattern.length];
        playPluckedTone(musicFreqCinder(bass - 12), time, MUSIC_STEP * 4.4, 0.044, "triangle", 360);
      }

      // Short dark stabs rather than a pretty melody.
      const motif = comp.motif[step];
      if (motif.hit && (step % 2 === 0 || motif.stab)) {
        playPluckedTone(
          musicFreqCinder(motif.note + 12),
          time + (motif.stab ? 0.010 : 0.028),
          MUSIC_STEP * (motif.stab ? 0.62 : 1.10),
          motif.stab ? 0.034 : 0.020,
          comp.melodyWave,
          motif.stab ? 820 : 980
        );
      }

      // Occasional dissonant warning tone, like heat bending the air.
      if (step % 16 === 13) {
        playPluckedTone(musicFreqCinder(comp.dangerTone + 24), time + MUSIC_STEP * 0.25, MUSIC_STEP * 2.7, 0.012, "sine", 1300);
      }

      musicStep++;
      musicNextStepTime += MUSIC_STEP * 0.82; // faster tempo feel for this biome
    }

    function musicFreqCinder(semitone) {
      const comp = cinderComposition || generateCinderComposition();
      return comp.root * Math.pow(2, semitone / 12);
    }

    function scheduleMysticStep(time) {
      const comp = mysticComposition || generateMysticComposition();
      const step = musicStep % 48;
      const phraseNote = comp.phrase[step];

      // Sparse breath instead of drums. It should feel like the forest is alive.
      if (step % 6 === 0 && Math.random() < comp.breathDensity) {
        playMysticBreath(time, 0.010);
      }

      // Slow, warm bass underneath.
      if (step % 8 === 0) {
        const bass = comp.bassPattern[Math.floor(step / 8) % comp.bassPattern.length];
        playPluckedTone(musicFreqMystic(bass - 12), time, MUSIC_STEP * 6.8, 0.022, "triangle", 520);
      }

      // Meditative melody: fewer notes, longer note tails.
      if (!phraseNote.rest && step % 3 === 0) {
        playPluckedTone(
          musicFreqMystic(phraseNote.note + 12),
          time + 0.020,
          MUSIC_STEP * phraseNote.length * 2.10,
          0.020,
          comp.melodyWave,
          1850
        );
      }

      // Beautiful bell notes. This is the Sakura identity.
      if (comp.bellSteps.includes(step) || phraseNote.bell) {
        playBellTone(
          musicFreqMystic((phraseNote.note || 0) + 24),
          time + MUSIC_STEP * 0.65,
          MUSIC_STEP * 5.5,
          0.015
        );
      }

      // Occasional very high shimmer.
      if (step % 24 === 18) {
        playBellTone(musicFreqMystic(comp.shimmerTone + 24), time + MUSIC_STEP * 1.15, MUSIC_STEP * 6.0, 0.010);
      }

      musicStep++;
      musicNextStepTime += MUSIC_STEP * 1.18; // calmer, slower-feeling than Cinder
    }

    function musicFreqMystic(semitone) {
      const comp = mysticComposition || generateMysticComposition();
      return comp.root * Math.pow(2, semitone / 12);
    }

    // ===== Biome Ambience Director =====
    // These are not melodies and not action sound effects.
    // They are low, static environmental beds + rare atmospheric one-shots.
    function createNoiseBuffer(seconds = 2.0) {
      const bufferSize = Math.floor(audioCtx.sampleRate * seconds);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) data[i] = Math.random() * 2 - 1;
      return buffer;
    }

    function createLoopingNoiseBed(name, filterType, freq, q, gainValue) {
      if (!audioCtx || !ambienceBus || ambienceSources[name]) return;

      const src = audioCtx.createBufferSource();
      src.buffer = createNoiseBuffer(2.5);
      src.loop = true;

      const filter = audioCtx.createBiquadFilter();
      filter.type = filterType;
      filter.frequency.value = freq;
      filter.Q.value = q;

      const g = audioCtx.createGain();
      g.gain.value = 0.0;
      g._targetBase = gainValue;

      src.connect(filter);
      filter.connect(g);
      g.connect(ambienceBus);

      src.start();
      ambienceSources[name] = { src, filter, gain: g };
    }

    function createLoopingToneBed(name, freq, gainValue, type = "sine") {
      if (!audioCtx || !ambienceBus || ambienceSources[name]) return;
      const osc = audioCtx.createOscillator();
      osc.type = type;
      osc.frequency.value = freq;

      const g = audioCtx.createGain();
      g.gain.value = 0.0;
      g._targetBase = gainValue;

      osc.connect(g);
      g.connect(ambienceBus);
      osc.start();
      ambienceSources[name] = { src: osc, filter: null, gain: g };
    }

    function initAmbienceSources() {
      if (ambienceSourcesReady || !audioCtx || !ambienceBus) return;
      ambienceSourcesReady = true;

      // Forest: soft leafy air.
      createLoopingNoiseBed("forestWind", "lowpass", 620, 0.45, 0.060);

      // Logging Pass: drier, lower, more exposed wind.
      createLoopingNoiseBed("loggingWind", "lowpass", 390, 0.55, 0.085);
      createLoopingToneBed("loggingLowAir", 58, 0.010, "sine");

      // Cinder Path: fire bed + ominous low pressure.
      createLoopingNoiseBed("cinderCrackle", "bandpass", 950, 1.35, 0.080);
      createLoopingNoiseBed("cinderSmoke", "lowpass", 260, 0.45, 0.040);
      createLoopingToneBed("cinderRumble", 42, 0.018, "sine");

      // Mystic Sakura: airy high night wind, not rhythmic.
      createLoopingNoiseBed("mysticAir", "bandpass", 1280, 0.55, 0.052);
      createLoopingToneBed("mysticDrone", 110, 0.010, "sine");

      // Start first one-shot timers.
      ambienceTimers.forestBird = 5 + Math.random() * 8;
      ambienceTimers.forestLeaves = 2 + Math.random() * 5;
      ambienceTimers.loggingCreak = 4 + Math.random() * 8;
      ambienceTimers.loggingThud = 7 + Math.random() * 11;
      ambienceTimers.cinderPop = 1.5 + Math.random() * 3.5;
      ambienceTimers.cinderHiss = 4 + Math.random() * 7;
      ambienceTimers.mysticLeaves = 2.5 + Math.random() * 5;
      ambienceTimers.mysticBell = 13 + Math.random() * 18;
    }

    function setAmbienceGain(name, amount, timeConstant = 0.45) {
      const src = ambienceSources[name];
      if (!src || !audioCtx) return;
      src.gain.gain.setTargetAtTime((src.gain._targetBase || 0) * amount, audioCtx.currentTime, timeConstant);
    }

    function playAmbienceNoise(start, duration, peak, filterType, freq, q = 1.0) {
      if (!audioCtx || !ambienceBus) return;
      const bufferSize = Math.max(1, Math.floor(audioCtx.sampleRate * duration));
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const env = Math.sin(Math.PI * (i / bufferSize));
        data[i] = (Math.random() * 2 - 1) * env;
      }

      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = filterType;
      filter.frequency.value = freq;
      filter.Q.value = q;

      const g = makeEnvelope(start, peak, 0.012, 0.060, peak * 0.28, 0.120, duration);
      src.connect(filter);
      filter.connect(g);
      g.connect(ambienceBus);
      src.start(start);
      src.stop(start + duration + 0.04);
    }

    function playAmbienceTone(freq, start, duration, peak, type = "sine") {
      if (!audioCtx || !ambienceBus) return;
      const osc = audioCtx.createOscillator();
      const g = makeEnvelope(start, peak, 0.015, 0.160, peak * 0.22, 0.300, duration);
      osc.type = type;
      osc.frequency.setValueAtTime(freq, start);
      osc.connect(g);
      g.connect(ambienceBus);
      osc.start(start);
      osc.stop(start + duration + 0.05);
    }

    function playForestBird(amount) {
      const now = audioCtx.currentTime;
      const base = 820 + Math.random() * 420;
      playAmbienceTone(base, now, 0.14, 0.018 * amount, "sine");
      playAmbienceTone(base * 1.18, now + 0.11, 0.12, 0.012 * amount, "sine");
    }

    function playForestLeaves(amount) {
      playAmbienceNoise(audioCtx.currentTime, 0.35 + Math.random() * 0.20, 0.014 * amount, "bandpass", 1800, 0.8);
    }

    function playLoggingCreak(amount) {
      const now = audioCtx.currentTime;
      playAmbienceTone(78 + Math.random() * 28, now, 0.42, 0.018 * amount, "sawtooth");
      playAmbienceNoise(now + 0.03, 0.18, 0.010 * amount, "lowpass", 360, 0.7);
    }

    function playLoggingThud(amount) {
      const now = audioCtx.currentTime;
      playAmbienceTone(58, now, 0.34, 0.028 * amount, "sine");
      playAmbienceNoise(now, 0.06, 0.014 * amount, "lowpass", 240, 0.6);
    }

    function playCinderPop(amount) {
      const now = audioCtx.currentTime;
      playAmbienceNoise(now, 0.055, 0.020 * amount, "highpass", 1200, 0.7);
      if (Math.random() < 0.45) playAmbienceTone(96 + Math.random() * 34, now, 0.16, 0.010 * amount, "triangle");
    }

    function playCinderHiss(amount) {
      playAmbienceNoise(audioCtx.currentTime, 0.62 + Math.random() * 0.28, 0.016 * amount, "bandpass", 2200, 0.5);
    }

    function playMysticLeaves(amount) {
      playAmbienceNoise(audioCtx.currentTime, 0.45 + Math.random() * 0.35, 0.012 * amount, "bandpass", 2600, 0.55);
    }

    function playMysticBellAmbience(amount) {
      const now = audioCtx.currentTime;
      const freq = [523.25, 587.33, 659.25, 783.99][Math.floor(Math.random() * 4)];
      playAmbienceTone(freq, now, 1.65, 0.012 * amount, "sine");
      playAmbienceTone(freq * 2.01, now + 0.015, 1.30, 0.006 * amount, "triangle");
    }

    // ===== SFX Director =====
    // Separate from music. Short arcade feedback sounds only.
    const SFX_GROUPS = {
      logRoll: ["03_log_roll_1", "03_log_roll_2", "03_log_roll_3"],
      humanAttack: ["07_human_atk_sword_1", "07_human_atk_sword_2", "07_human_atk_sword_3"],
      humanAttack1: ["07_human_atk_sword_1"],
      humanAttack2: ["07_human_atk_sword_2"],
      humanAttack3: ["07_human_atk_sword_3"],
      humanSpecial1: ["10_human_special_atk_1"],
      humanSpecial2: ["10_human_special_atk_2"],
      humanDamage: ["11_human_damage_1", "11_human_damage_2", "11_human_damage_3"],
      humanJump: ["12_human_jump_1", "12_human_jump_2", "12_human_jump_3"],
      humanLand: ["13_human_jump_land_1", "13_human_jump_land_2"],
      humanDeath: ["14_human_death_spin"],
      humanDash: ["15_human_dash_1", "15_human_dash_2"],
      humanFootstep: ["16_human_walk_stone_1", "16_human_walk_stone_2", "16_human_walk_stone_3"],
      orcAttack: ["17_orc_atk_sword_1", "17_orc_atk_sword_2", "17_orc_atk_sword_3"],
      orcCharge: ["18_orc_charge"],
      orcChargingLoop: ["19_orc_charging_loop"],
      orcSpecial: ["20_orc_special_atk"],
      orcDamage: ["21_orc_damage_1", "21_orc_damage_2", "21_orc_damage_3"],
      orcJump: ["22_orc_jump_1", "22_orc_jump_2"],
      orcLand: ["23_orc_jump_land"],
      orcDeath: ["24_orc_death_spin"],
      orcFootstep: ["25_orc_walk_stone_1", "25_orc_walk_stone_2", "25_orc_walk_stone_3"],
      swordHit: ["26_sword_hit_1", "26_sword_hit_2", "26_sword_hit_3"],
      swordMiss: ["27_sword_miss_1", "27_sword_miss_2", "27_sword_miss_3"]
    };

    function pickSfx(name) {
      const group = SFX_GROUPS[name];
      if (group) return group[Math.floor(Math.random() * group.length)];
      return name;
    }

    async function ensureSfxDecoded() {
      if (!audioCtx || sfxDecodeStarted) return;
      sfxDecodeStarted = true;
      const entries = Object.entries(SFX_SOURCES);
      await Promise.all(entries.map(async ([name, src]) => {
        try {
          const response = await fetch(src);
          const arrayBuffer = await response.arrayBuffer();
          sfxBuffers[name] = await audioCtx.decodeAudioData(arrayBuffer);
        } catch (err) {
          console.warn("SFX decode failed:", name, err);
        }
      }));
      sfxDecodeReady = true;
    }

    function playSfx(name, volume = 1.0, rate = 1.0, cooldownMs = 0) {
      if (!audioCtx || !sfxBus || musicMuted) return;
      ensureSfxDecoded();
      const id = pickSfx(name);
      const buffer = sfxBuffers[id];
      if (!buffer) return;

      const nowMs = performance.now();
      if (cooldownMs > 0 && sfxCooldowns[name] && nowMs < sfxCooldowns[name]) return;
      if (cooldownMs > 0) sfxCooldowns[name] = nowMs + cooldownMs;

      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.playbackRate.value = rate;

      const gain = audioCtx.createGain();
      gain.gain.value = Math.max(0, Math.min(1.4, volume));

      source.connect(gain);
      gain.connect(sfxBus);
      source.start();
    }

    function play8BitThud(volume = 0.9) {
      if (!audioCtx || !sfxBus || musicMuted) return;
      const now = audioCtx.currentTime;
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = "square";
      osc.frequency.setValueAtTime(82, now);
      osc.frequency.exponentialRampToValueAtTime(32, now + 0.20);
      gain.gain.setValueAtTime(0.001, now);
      gain.gain.exponentialRampToValueAtTime(volume, now + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.34);
      osc.connect(gain);
      gain.connect(sfxBus);
      osc.start(now);
      osc.stop(now + 0.36);
    }

    function playEarthquakeShake(volume = 0.55, duration = 0.72) {
      if (!audioCtx || !sfxBus || musicMuted) return;
      const now = audioCtx.currentTime;
      const bufferSize = Math.floor(audioCtx.sampleRate * duration);
      const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        const env = Math.pow(1 - i / bufferSize, 1.4);
        data[i] = (Math.random() * 2 - 1) * env;
      }
      const src = audioCtx.createBufferSource();
      src.buffer = buffer;
      const filter = audioCtx.createBiquadFilter();
      filter.type = "lowpass";
      filter.frequency.setValueAtTime(260, now);
      filter.frequency.exponentialRampToValueAtTime(90, now + duration);
      const gain = audioCtx.createGain();
      gain.gain.setValueAtTime(0.001, now);
      gain.gain.exponentialRampToValueAtTime(volume, now + 0.035);
      gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
      src.connect(filter);
      filter.connect(gain);
      gain.connect(sfxBus);
      src.start(now);
      src.stop(now + duration + 0.02);
    }

    function playEnemyAttackSfx(enemy, name) {
      if (enemy.type === "executioner" && name === "attack1") return;
      if (enemy.type === "executioner" || enemy.type === "panda" || enemy.isOni || enemy.isFireOni) {
        if (name === "dashAttack" || name === "strongAttack" || name === "jumpAttack" || name === "specialAttack") {
          playSfx("orcSpecial", 0.88, 0.88 + Math.random() * 0.10, 120);
        } else {
          playSfx("orcAttack", 0.62, 0.88 + Math.random() * 0.16, 90);
        }
      } else {
        playSfx("orcAttack", 0.44, 0.94 + Math.random() * 0.12, 80);
      }
    }

    function updateFootstepSfx(dt) {
      if (!p1WasGroundedForSfx && player.grounded && !player.dead) playSfx("humanLand", 0.45, 0.95 + Math.random() * 0.10, 80);
      p1WasGroundedForSfx = player.grounded;

      if (player2.active) {
        if (!p2WasGroundedForSfx && player2.grounded && !player2.dead) playSfx("humanLand", 0.38, 1.04 + Math.random() * 0.10, 80);
        p2WasGroundedForSfx = player2.grounded;
      }

      p1StepTimer -= dt;
      const p1Speed = Math.abs(player.vx) + Math.abs(player.vy) * 0.75;
      const p1Locked = player.actionTimer > 0 || player.hurtTimer > 0 || player.block || player.dead;
      if (player.grounded && !p1Locked && p1Speed > 0.28 && p1StepTimer <= 0) {
        const interval = clamp(270 - p1Speed * 50, 92, 270);
        playSfx("humanFootstep", 0.38 + Math.min(0.24, p1Speed * 0.055), 0.88 + Math.random() * 0.22, 35);
        p1StepTimer = interval;
      }

      if (player2.active) {
        p2StepTimer -= dt;
        const p2Speed = Math.abs(player2.vx) + Math.abs(player2.vy) * 0.75;
        const p2Locked = player2.actionTimer > 0 || player2.hurtTimer > 0 || player2.block || player2.dead;
        if (player2.grounded && !p2Locked && p2Speed > 0.28 && p2StepTimer <= 0) {
          const interval = clamp(285 - p2Speed * 50, 100, 285);
          playSfx("humanFootstep", 0.32 + Math.min(0.22, p2Speed * 0.050), 1.02 + Math.random() * 0.18, 35);
          p2StepTimer = interval;
        }
      }
    }

    function initMp3Soundtrack() {
      // Placeholder kept for compatibility with HUD/mute code.
      // Actual decoding starts from ensureMp3SoundtrackStarted() after user gesture.
      if (!mp3Tracks.length) mp3Tracks = STAGE_TRACKS.slice();
    }

    function stageTrackIndexForMetres(m) {
      // Stage 1: 0-999m
      // Stage 2: 1000-1999m
      // Stage 3: 2000-2999m
      // Stage 4: 3000-3999m
      // Stage 5: 4000-4999m
      // After 5000m, cycle from Stage 1 again every 1000m.
      if (m < 1000) return 0;
      if (m < 2000) return 1;
      if (m < 3000) return 2;
      if (m < 4000) return 3;
      if (m < 5000) return 4;
      return Math.floor((m - 5000) / 1000) % 5;
    }

    async function decodeStageTrack(track) {
      const response = await fetch(track.src);
      const arrayBuffer = await response.arrayBuffer();
      return await audioCtx.decodeAudioData(arrayBuffer);
    }

    function stopMp3Sources() {
      for (const src of mp3TrackSources) {
        try { if (src) src.stop(); } catch (e) {}
      }
      mp3TrackSources = [];
      mp3TrackGains = [];
      currentMp3Index = -1;
    }

    function stopMenuMusic() {
      if (menuMusicGain && audioCtx) menuMusicGain.gain.setTargetAtTime(0, audioCtx.currentTime, 0.10);
      if (menuMusicSource) {
        const oldSource = menuMusicSource;
        setTimeout(() => {
          try { oldSource.stop(); } catch (e) {}
        }, 450);
      }
      menuMusicSource = null;
      menuMusicGain = null;
    }

    function fadeOutStageTracksForMenu() {
      if (!audioCtx) return;
      for (let i = 0; i < mp3TrackSources.length; i++) {
        const src = mp3TrackSources[i];
        const gain = mp3TrackGains[i];
        if (!src) continue;
        if (gain) gain.gain.setTargetAtTime(0, audioCtx.currentTime, 0.16);
        const oldSource = src;
        setTimeout(() => {
          try { oldSource.stop(); } catch (e) {}
        }, 700);
        mp3TrackSources[i] = null;
        mp3TrackGains[i] = null;
      }
      currentMp3Index = -1;
    }

    function startMenuMusic() {
      if (!audioCtx || !musicBus || !mp3DecodeReady || !menuMusicBuffer) return;

      // Always fade out any active game music when returning to menu/pause.
      fadeOutStageTracksForMenu();

      if (!menuMusicSource) {
        menuMusicSource = audioCtx.createBufferSource();
        menuMusicSource.buffer = menuMusicBuffer;
        menuMusicSource.loop = true;

        menuMusicGain = audioCtx.createGain();
        menuMusicGain.gain.value = 0;

        menuMusicSource.connect(menuMusicGain);
        menuMusicGain.connect(musicBus);
        menuMusicSource.start(audioCtx.currentTime + 0.03);
      }

      if (menuMusicGain) menuMusicGain.gain.setTargetAtTime(musicVolume * 0.78, audioCtx.currentTime, 0.28);
      if (musicBus) musicBus.gain.setTargetAtTime(1.0, audioCtx.currentTime, 0.12);
    }

    function createStageSource(index) {
      if (!audioCtx || !musicBus || !mp3DecodeReady || !mp3TrackBuffers[index]) return null;

      const source = audioCtx.createBufferSource();
      source.buffer = mp3TrackBuffers[index];
      source.loop = true;

      const gain = audioCtx.createGain();
      gain.gain.value = 0;

      source.connect(gain);
      gain.connect(musicBus);
      source.start(audioCtx.currentTime + 0.03);

      mp3TrackSources[index] = source;
      mp3TrackGains[index] = gain;
      return { source, gain };
    }

    function startDecodedMp3Sources() {
      if (!audioCtx || !musicBus || !mp3DecodeReady) return;

      if (gameState === "menu" || gameState === "options" || gameState === "paused") {
        startMenuMusic();
      } else {
        // Do NOT force here. ensureAudioStarted() is called on every keypress;
        // forcing would restart the current song constantly.
        switchMp3Track(stageTrackIndexForMetres(distanceMetres()), false);
      }
    }

    function ensureMp3SoundtrackStarted() {
      initMp3Soundtrack();
      musicStarted = true;
      pendingMp3Index = stageTrackIndexForMetres(distanceMetres());

      if (mp3DecodeReady) {
        // Already decoded. Only make sure the correct source exists;
        // never restart the currently playing stage track from a keypress.
        startDecodedMp3Sources();
        return;
      }

      if (mp3DecodeStarted || !audioCtx) return;
      mp3DecodeStarted = true;

      Promise.all([
        Promise.all(STAGE_TRACKS.map(decodeStageTrack)),
        decodeStageTrack(MENU_MUSIC_TRACK)
      ]).then(([buffers, menuBuffer]) => {
        mp3TrackBuffers = buffers;
        menuMusicBuffer = menuBuffer;
        mp3DecodeReady = true;
        startDecodedMp3Sources();
      }).catch(err => {
        console.warn("MP3 soundtrack decode failed:", err);
      });
    }

    function switchMp3Track(index, force = false) {
      if (index < 0 || index >= STAGE_TRACKS.length) return;
      pendingMp3Index = index;
      if (!mp3DecodeReady) return;

      if (menuMusicGain && audioCtx) menuMusicGain.gain.setTargetAtTime(0, audioCtx.currentTime, 0.16);

      if (!force && index === currentMp3Index && mp3TrackGains[index]) return;

      // Fade/stop old active stage sources so the new biome song starts from the beginning.
      for (let i = 0; i < mp3TrackSources.length; i++) {
        if (i === index) continue;
        const oldGain = mp3TrackGains[i];
        const oldSource = mp3TrackSources[i];
        if (oldGain && audioCtx) oldGain.gain.setTargetAtTime(0, audioCtx.currentTime, 0.18);
        if (oldSource) {
          setTimeout(() => {
            try { oldSource.stop(); } catch (e) {}
          }, 650);
        }
        mp3TrackSources[i] = null;
        mp3TrackGains[i] = null;
      }

      if (mp3TrackSources[index]) {
        try { mp3TrackSources[index].stop(); } catch (e) {}
      }
      mp3TrackSources[index] = null;
      mp3TrackGains[index] = null;

      createStageSource(index);
      currentMp3Index = index;
      mp3FadeTimer = MP3_FADE_SECONDS;
    }

    function updateMp3StageMusic(dt) {
      if (!musicStarted || musicMuted) return;

      if (!mp3DecodeReady) {
        ensureMp3SoundtrackStarted();
        return;
      }

      if (gameState !== "playing") return;

      const nextIndex = stageTrackIndexForMetres(distanceMetres());
      switchMp3Track(nextIndex);

      const now = audioCtx.currentTime;
      for (let i = 0; i < mp3TrackGains.length; i++) {
        if (!mp3TrackGains[i]) continue;
        const target = i === currentMp3Index ? musicVolume : 0;
        mp3TrackGains[i].gain.setTargetAtTime(target, now, MP3_FADE_SECONDS / 3.0);
      }
    }

    function updateMenuMusic(dt) {
      if (!musicStarted || musicMuted) return;
      if (!mp3DecodeReady) {
        ensureMp3SoundtrackStarted();
        return;
      }
      startMenuMusic();
    }

    function updateAmbience(dt) {
      // Procedural ambience disabled in this MP3 soundtrack test build.
    }

    function updateProceduralMusic() {
      // Procedural music disabled in this MP3 soundtrack test build.
    }

    function toggleMusicMute() {
      musicMuted = !musicMuted;
      if (musicMuted) {
        if (musicBus && audioCtx) musicBus.gain.setTargetAtTime(0, audioCtx.currentTime, 0.08);
        if (sfxBus && audioCtx) sfxBus.gain.setTargetAtTime(0, audioCtx.currentTime, 0.08);
      } else {
        ensureAudioStarted();
        if (musicBus && audioCtx) musicBus.gain.setTargetAtTime(1.0, audioCtx.currentTime, 0.08);
        if (sfxBus && audioCtx) sfxBus.gain.setTargetAtTime(sfxVolume, audioCtx.currentTime, 0.08);
      }
    }

    // Create the first unique run tune immediately; audio still waits for input.
    reseedForestMusic(runMusicSeed);

        const MOON_SKY_4000_URL = "data:image/png;base64,";

const MYSTIC_SAKURA_BG_1_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_2_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_3_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_4_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_5_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_6_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_7_URL = "data:image/png;base64,";
    const MYSTIC_SAKURA_BG_8_URL = "data:image/png;base64,";
    window.addEventListener("pointerdown", ensureAudioStarted);
    window.addEventListener("touchstart", ensureAudioStarted, { passive: true });

    window.addEventListener("keydown", e => {
      ensureAudioStarted();
      const k = e.key.toLowerCase();
      const code = e.code;
      if (k === "m" && !keys.has(k)) toggleMusicMute();
      if ([" ", "arrowup", "arrowdown", "arrowleft", "arrowright", "shift"].includes(k)) e.preventDefault();
      const already = keys.has(k);
      const codeAlready = keyCodes.has(code);
      keys.add(k);
      keyCodes.add(code);
      if (!already) justPressed.add(k);
      if (!codeAlready) justPressedCodes.add(code);

      if (!already) {
        const now = performance.now();
        if (k === "d") {
          if (now - lastRightTap <= DOUBLE_TAP_MS) sprintDir = 1;
          lastRightTap = now;
        }
        if (k === "a") {
          if (now - lastLeftTap <= DOUBLE_TAP_MS) sprintDir = -1;
          lastLeftTap = now;
        }

        if (k === "arrowright") {
          if (now - player2LastRightTap <= DOUBLE_TAP_MS) {
            player2SprintDir = 1;
            player2SprintTimer = 520;
          }
          player2LastRightTap = now;
        }
        if (k === "arrowleft") {
          if (now - player2LastLeftTap <= DOUBLE_TAP_MS) {
            player2SprintDir = -1;
            player2SprintTimer = 520;
          }
          player2LastLeftTap = now;
        }
      }
    });
    window.addEventListener("keyup", e => {
      const k = e.key.toLowerCase();
      const code = e.code;
      keys.delete(k);
      keyCodes.delete(code);
      if (k === "d" && sprintDir === 1) sprintDir = 0;
      if (k === "a" && sprintDir === -1) sprintDir = 0;
      if (k === "arrowright" && player2SprintDir === 1) {
        player2SprintDir = 0;
        player2SprintTimer = 0;
      }
      if (k === "arrowleft" && player2SprintDir === -1) {
        player2SprintDir = 0;
        player2SprintTimer = 0;
      }
    });
    function updateMouseCanvasPosition(e) {
      const rect = canvas.getBoundingClientRect();
      mouse.x = (e.clientX - rect.left) * (W / rect.width);
      mouse.y = (e.clientY - rect.top) * (H / rect.height);
    }

    window.addEventListener("mousemove", e => {
      updateMouseCanvasPosition(e);
      if ((gameState === "options" || gameState === "paused") && draggingOptionSlider) {
        if (draggingOptionSlider === "music") setMusicVolumeFromX(mouse.x);
        if (draggingOptionSlider === "sfx") setSfxVolumeFromX(mouse.x);
      }
    });

    window.addEventListener("mousedown", e => {
      updateMouseCanvasPosition(e);
      if (gameState !== "playing" && e.button === 0) {
        ensureAudioStarted();
        handleMenuClick(mouse.x, mouse.y);
        e.preventDefault();
        return;
      }
      if (e.button === 0 && gameState === "playing" && bothPlayersFullyDead()) {
        if (rectHit(mouse.x,mouse.y,174,246,140,32)) {
          seasonFinishRun(); quitToMainMenu(); gameState="leaderboard"; seasonRefreshBoard(); e.preventDefault(); return;
        }
        if (rectHit(mouse.x,mouse.y,330,246,140,32)) {
          seasonReturnToMenuAfterDeath(); e.preventDefault(); return;
        }
      }
      if (e.button === 0) { mouse.left = true; mouse.justLeft = true; }
      if (e.button === 1) { mouse.middle = true; mouse.justMiddle = true; e.preventDefault(); }
      if (e.button === 2) mouse.right = true;
    });
    window.addEventListener("mouseup", e => {
      if (e.button === 0) {
        mouse.left = false;
        draggingOptionSlider = null;
      }
      if (e.button === 1) mouse.middle = false;
      if (e.button === 2) mouse.right = false;
    });
    window.addEventListener("auxclick", e => {
      if (e.button === 1) {
        mouse.justMiddle = true;
        mouse.middle = true;
        e.preventDefault();
      }
    });
    window.addEventListener("contextmenu", e => e.preventDefault());

