    const RONIN_TEST_ANIMS = ["idle", "run", "defend", "attack1", "attack2", "attack3", "strongAttack", "dash", "throw", "jump", "hurt", "death"];
    let roninTest = {
      active: false,
      x: 0,
      roadY: 0,
      facing: -1,
      animName: "idle",
      animTimer: 0,
      animTotal: 0,
      animIndex: 0,
      walkSeed: 0
    };

    function startRoninTestAnim(name) {
      const anim = RONIN_ANIMS[name] || RONIN_ANIMS.idle;
      roninTest.animName = name;
      roninTest.animTotal = anim.frames * (1000 / anim.fps);
      roninTest.animTimer = anim.loop ? 0 : roninTest.animTotal;
      const idx = RONIN_TEST_ANIMS.indexOf(name);
      if (idx >= 0) roninTest.animIndex = idx;
    }

    function spawnRoninTest() {
      roninTest.active = true;
      roninTest.x = player.x + 170;
      roninTest.roadY = clamp(player.roadY + 8, ROAD_TOP + 12, ROAD_BOTTOM);
      roninTest.facing = -1;
      roninTest.walkSeed = Math.random() * 1000;
      startRoninTestAnim("idle");
    }

    function cycleRoninTestAnim() {
      if (!roninTest.active) spawnRoninTest();
      roninTest.animIndex = (roninTest.animIndex + 1) % RONIN_TEST_ANIMS.length;
      startRoninTestAnim(RONIN_TEST_ANIMS[roninTest.animIndex]);
    }

    function updateRoninTest(dt) {
      if (!roninTest.active) return;

      if (roninTest.animTimer > 0) {
        roninTest.animTimer = Math.max(0, roninTest.animTimer - dt);
        if (roninTest.animTimer === 0) startRoninTestAnim("idle");
      }

      // Keep test Ronin just ahead of the player for easy inspection,
      // but don't run AI or collision yet.
      if (roninTest.x < player.x + 120) roninTest.x = player.x + 160;
      roninTest.roadY = clamp(roninTest.roadY, ROAD_TOP + 12, ROAD_BOTTOM);
    }

    function forceSpawnRoninEnemy(offset = 180) {
      spawnEnemy(currentLeadHero().x + offset, "ronin");
      const newest = enemies[enemies.length - 1];
      if (newest && newest.type === "ronin") {
        newest.roadY = clamp(player.roadY + 8, ROAD_TOP + 12, ROAD_BOTTOM);
        newest.facing = -1;
        newest.vx = 0;
        newest.vy = 0;
        newest.attackCooldown = 350;
        newest.dashCooldown = 250;
        newest.throwCooldown = 700 + Math.random() * 500;
        newest.throwDone = false;
      }
    }

    function distanceMetres() {
      const heroes = livingHeroes();
      if (heroes.length === 0) return runBestDistance;
      const progressHero = currentLeadHero();
      return Math.max(runBestDistance, Math.max(0, Math.floor((progressHero.x - START_X) / 10)));
    }

    function metresAtWorldX(worldX) {
      return Math.max(0, Math.floor((worldX - START_X) / 10));
    }

    function loggingPassBlendForMetres(m) {
      // Soft transition from the last part of The Forest into The Logging Pass.
      // 0 = normal Forest, 1 = full Logging Pass.
      return clamp((m - 960) / 80, 0, 1);
    }

    function scorchedRoadBlendForMetres(m) {
      // Soft transition from The Logging Pass into the scorched realm.
      return clamp((m - 1960) / 90, 0, 1);
    }

    function scorchedBlend() {
      return scorchedRoadBlendForMetres(distanceMetres());
    }

    function isScorchedRoadWorldX(worldX) {
      return metresAtWorldX(worldX) >= 2000;
    }

    function scorchedBlendForWorldX(worldX) {
      return scorchedRoadBlendForMetres(metresAtWorldX(worldX));
    }

    function sakuraBlendForMetres(m) {
      // Soft transition from Cinder Path into the final Mystic Sakura Forest.
      return clamp((m - 2940) / 120, 0, 1);
    }

    function sakuraBlend() {
      return sakuraBlendForMetres(distanceMetres());
    }

    function isMysticSakuraWorldX(worldX) {
      return metresAtWorldX(worldX) >= 3000;
    }

    function sakuraBlendForWorldX(worldX) {
      return sakuraBlendForMetres(metresAtWorldX(worldX));
    }

    function teleportToScorchedRoad() {
      const targetX = START_X + 20000; // 2000m
      player.x = targetX;
      player.vx = 0;
      player.vy = 0;
      player.z = 0;
      player.vz = 0;
      player.roadY = clamp(player.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);

      if (player2.active && !player2.dead) {
        player2.x = targetX - 55;
        player2.vx = 0;
        player2.vy = 0;
        player2.z = 0;
        player2.vz = 0;
        player2.roadY = clamp(player2.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);
      }
    }

    function teleportToMysticSakura() {
      const targetX = START_X + 30000; // 3000m
      player.x = targetX;
      player.vx = 0;
      player.vy = 0;
      player.z = 0;
      player.vz = 0;
      player.roadY = clamp(player.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);

      if (player2.active && !player2.dead) {
        player2.x = targetX - 55;
        player2.vx = 0;
        player2.vy = 0;
        player2.z = 0;
        player2.vz = 0;
        player2.roadY = clamp(player2.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);
      }
    }

    function teleportToMoonlitSakura() {
      const targetX = START_X + 40000; // 4000m
      player.x = targetX;
      player.vx = 0;
      player.vy = 0;
      player.z = 0;
      player.vz = 0;
      player.roadY = clamp(player.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);

      if (player2.active && !player2.dead) {
        player2.x = targetX - 55;
        player2.vx = 0;
        player2.vy = 0;
        player2.z = 0;
        player2.vz = 0;
        player2.roadY = clamp(player2.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);
      }

      runBestDistance = Math.max(runBestDistance, 4000);
      nextEnemySpawnMetre = Math.max(nextEnemySpawnMetre, 4000);
      if (typeof enemySpawnCooldown !== "undefined") enemySpawnCooldown = 900;
    }

    function loggingPassBlend() {
      return loggingPassBlendForMetres(distanceMetres());
    }

    function isLoggingPassWorldX(worldX) {
      return metresAtWorldX(worldX) >= 1000;
    }

    function teleportToLoggingPass() {
      const targetX = START_X + 10000; // 1000m
      player.x = targetX;
      player.vx = 0;
      player.vy = 0;
      player.z = 0;
      player.vz = 0;
      player.roadY = clamp(player.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);

      if (player2.active && !player2.dead) {
        player2.x = targetX - 55;
        player2.vx = 0;
        player2.vy = 0;
        player2.z = 0;
        player2.vz = 0;
        player2.roadY = clamp(player2.roadY, ROAD_TOP + 18, ROAD_BOTTOM - 8);
      }

      nextEnemySpawnMetre = Math.max(nextEnemySpawnMetre, 1000);
      if (typeof enemySpawnCooldown !== "undefined") enemySpawnCooldown = 0;
      window._windWorldParticles = null;
      executionerCooldown(false); executionerShadow.timer = 500;
    }

    function startAction(name) {
      const anim = PLAYER_ANIMS[name];
      player.actionName = name;
      player.actionFrameMs = 1000 / anim.fps;
      player.actionTotal = anim.frames * player.actionFrameMs;
      player.actionTimer = player.actionTotal;

      if (name === "attack1") playSfx("humanAttack1", 0.48, 0.96 + Math.random() * 0.08, 40);
      else if (name === "attack2") playSfx("humanAttack2", 0.50, 0.96 + Math.random() * 0.08, 40);
      else if (name === "attack3" || name === "airAttack") playSfx("humanAttack3", 0.52, 0.96 + Math.random() * 0.08, 40);
      else if (name === "specialAttack") playSfx("humanSpecial1", 0.68, 0.96, 80);
      else if (name === "dash") playSfx("humanDash", 0.48, 0.98 + Math.random() * 0.08, 80);
      else if (name === "death") playSfx("humanDeath", 0.72, 0.96, 200);
    }

    function startJumpSequence() {
      if (!player.grounded || player.dead || player.actionTimer > 0 || player.hurtTimer > 0) return;

      // Jump should happen immediately on button press.
      // The Jump Start animation now plays during the first part of upward movement,
      // instead of delaying the jump launch.
      player.grounded = false;
      player.vz = 5.8;
      playSfx("humanJump", 0.42, 0.96 + Math.random() * 0.10, 80);

      const a = PLAYER_ANIMS.jumpStart;
      player.jumpStartTotal = Math.min(110, a.frames * (1000 / a.fps));
      player.jumpStartTimer = player.jumpStartTotal;

      const t = PLAYER_ANIMS.jumpTransition;
      player.jumpTransitionTotal = t.frames * (1000 / t.fps);
      player.jumpTransitionTimer = 0;
    }

    function triggerHurt() {
      const a = PLAYER_ANIMS.hurt;
      player.hurtTotal = a.frames * (1000 / a.fps);
      player.hurtTimer = player.hurtTotal;
      player.actionTimer = 0;
      player.actionName = "";
    }


    function joinPlayer2() {
      if (player2.joinedThisRun || player2.active) return;
      seasonMarkDuo();
      player2.active = true;
      player2.joinedThisRun = true;
      player2.dead = false;
      player2.hp = 100;
      player2.x = player.x - 42;
      player2.roadY = clamp(player.roadY + 12, ROAD_TOP + 12, ROAD_BOTTOM);
      player2.z = 0;
      player2.vx = player2.vy = player2.vz = 0;
      player2.facing = player.facing;
      player2.grounded = true;
      player2.actionName = "";
      player2.actionTimer = 0;
      player2.hurtTimer = 0;
      player2.block = false;
      player2.throwDone = false;
    }

    function joinGrandfatherWhenGranddaughterStarted() {
      if (selectedPlayer1Character !== "granddaughter") return;
      if (!player2.active || player2.dead) return;
      if (!player.dead && player.hp > 0) return;
      seasonMarkDuo();

      player.dead = false;
      player.hp = 100;
      player.deathDistance = 0;
      player.x = Math.max(START_X, player2.x - 48);
      player.roadY = clamp(player2.roadY + 10, ROAD_TOP + 12, ROAD_BOTTOM);
      player.z = 0;
      player.vx = player.vy = player.vz = 0;
      player.facing = player2.facing || 1;
      player.grounded = true;
      player.invulnTimer = 0;
      player.walkClock = 0;
      player.actionName = "";
      player.actionTimer = 0;
      player.hurtTimer = 0;
      player.jumpStartTimer = 0;
      player.jumpTransitionTimer = 0;
      player.block = false;
      player.blockSparkTimer = 0;
      player.comboStep = 0;
      player.comboQueued = 0;
      player.comboTimer = 0;
      player.dashLock = 0;
      player.dashAttackWindow = 0;
      player.dashRecoveryTimer = 0;
      player.dashCooldownTimer = 0;
      player.dashInvulnTimer = 0;
    }

    function livingHeroes() {
      const heroes = [];
      if (!player.dead) heroes.push(player);
      if (player2.active && !player2.dead) heroes.push(player2);
      return heroes;
    }

    function currentLeadHero() {
      const heroes = livingHeroes();
      if (heroes.length === 0) {
        if (player2.active) {
          return ((player2.deathDistance || metresAtWorldX(player2.x)) > (player.deathDistance || metresAtWorldX(player.x))) ? player2 : player;
        }
        return player;
      }

      let best = heroes[0];
      for (const h of heroes) {
        if (h.x > best.x) best = h;
      }
      return best;
    }

    function updateRunBestDistance() {
      runBestDistance = Math.max(runBestDistance, metresAtWorldX(player.x || START_X));
      if (player2.active) runBestDistance = Math.max(runBestDistance, metresAtWorldX(player2.x || START_X));
    }

    function closestLivingHero(enemy) {
      const heroes = livingHeroes();
      if (heroes.length === 0) return player;
      let best = heroes[0];
      let bestScore = Infinity;
      for (const h of heroes) {
        const dx = Math.abs(h.x - enemy.x);
        const dy = Math.abs(h.roadY - enemy.roadY);
        const score = dx + dy * 1.25;
        if (score < bestScore) {
          best = h;
          bestScore = score;
        }
      }
      return best;
    }

    function withEnemyTarget(enemy, target, fn) {
      // Most enemy AI was originally written against the global `player`.
      // To avoid rewriting every enemy from scratch, temporarily mirror the chosen
      // hero into the original player object while that enemy thinks/attacks,
      // then copy any damage/death changes back to the actual target.
      if (target === player) return fn();

      const saved = {
        x: player.x, roadY: player.roadY, z: player.z,
        vx: player.vx, vy: player.vy, vz: player.vz,
        facing: player.facing, grounded: player.grounded,
        hp: player.hp, dead: player.dead, invulnTimer: player.invulnTimer,
        block: player.block, blockSparkTimer: player.blockSparkTimer,
        hurtTimer: player.hurtTimer, actionName: player.actionName,
        actionTimer: player.actionTimer, deathDistance: player.deathDistance
      };

      player.x = target.x;
      player.roadY = target.roadY;
      player.z = target.z;
      player.vx = target.vx;
      player.vy = target.vy;
      player.vz = target.vz;
      player.facing = target.facing;
      player.grounded = target.grounded;
      player.hp = target.hp;
      player.dead = target.dead;
      player.invulnTimer = target.invulnTimer;
      player.block = target.block;
      player.blockSparkTimer = target.blockSparkTimer;
      player.hurtTimer = target.hurtTimer;
      player.actionName = target.actionName;
      player.actionTimer = target.actionTimer;

      fn();

      target.x = player.x;
      target.roadY = player.roadY;
      target.z = player.z;
      target.vx = player.vx;
      target.vy = player.vy;
      target.vz = player.vz;
      target.facing = player.facing;
      target.grounded = player.grounded;
      target.hp = player.hp;
      target.dead = player.dead;
      target.invulnTimer = player.invulnTimer;
      target.block = player.block;
      target.blockSparkTimer = player.blockSparkTimer;
      target.hurtTimer = player.hurtTimer;

      // If mirrored damage killed Player 2, start her death animation.
      if (target === player2 && target.dead && target.actionName !== "death") {
        startPlayer2Action("death");
      }

      Object.assign(player, saved);
    }

    function heroAttackHitbox(hero) {
      if (hero === player) return playerAttackHitbox();
      return player2AttackHitbox();
    }

    function bothPlayersDead() {
      return player.dead && (!player2.active || player2.dead);
    }

    function heroDeathAnimDone(hero) {
      return !hero.dead || hero.actionName !== "death" || hero.actionTimer <= 0;
    }

    function bothPlayersFullyDead() {
      return bothPlayersDead() && heroDeathAnimDone(player) && (!player2.active || heroDeathAnimDone(player2));
    }

    function startPlayer2Action(name) {
      const anim = PLAYER2_ANIMS[name];
      if (!anim) return;
      player2.actionName = name;
      player2.actionFrameMs = 1000 / anim.fps;
      player2.actionTotal = anim.frames * player2.actionFrameMs;
      player2.actionTimer = player2.actionTotal;
      if (name === "throw") player2.throwDone = false;

      if (name === "attack1") playSfx("humanAttack1", 0.40, 1.05 + Math.random() * 0.08, 40);
      else if (name === "attack2") playSfx("humanAttack2", 0.42, 1.05 + Math.random() * 0.08, 40);
      else if (name === "attack3") playSfx("humanAttack3", 0.44, 1.05 + Math.random() * 0.08, 40);
      else if (name === "specialAttack") playSfx("humanSpecial2", 0.62, 1.04, 80);
      else if (name === "death") playSfx("humanDeath", 0.62, 1.05, 200);
    }

    function triggerPlayer2Hurt() {
      const a = PLAYER2_ANIMS.hurt;
      player2.hurtTotal = a.frames * (1000 / a.fps);
      player2.hurtTimer = player2.hurtTotal;
      player2.actionTimer = 0;
      player2.actionName = "";
    }

    function damageHero(hero, amount, knockDir) {
      if (hero.invulnTimer > 0 || hero.dead) return;
      const blocked = hero.block && Math.sign(knockDir) !== hero.facing;
      if (blocked) {
        // Blocking now fully negates damage for all players.
        hero.vx += knockDir * 0.55;
        hero.blockSparkTimer = hero.blockSparkTotal;
        hero.invulnTimer = 260;
        playSfx("swordHit", 0.42, 1.08 + Math.random() * 0.10, 80);
        return;
      } else {
        hero.vx += knockDir * 2.1;
        playSfx("humanDamage", hero === player2 ? 0.42 : 0.54, hero === player2 ? 1.08 : 0.98, 120);
        if (hero === player2) triggerPlayer2Hurt();
        else triggerHurt();
      }
      hero.hp -= amount;
      hero.invulnTimer = 650;
      if (hero.hp <= 0) {
        hero.hp = 0;
        hero.dead = true;
        hero.block = false;
        hero.deathDistance = Math.max(hero.deathDistance || 0, metresAtWorldX(hero.x));
        runBestDistance = Math.max(runBestDistance, hero.deathDistance);
        if (hero === player2) startPlayer2Action("death");
        else startAction("death");
      }
    }

