    function drawLake(cam) {
      fill(0, 212, W, 36, "#77bfd4");
      fill(0, 220, W, 2, "#e6fbff");
      for (let i = 0; i < 42; i++) {
        const x = ((i * 32 - cam * 0.23) % (W + 70)) - 30;
        fill(x, 218 + (i % 5) * 5, 20, 1, "#eefcff");
      }
    }
    function drawPagodaAndBridge(cam) {
      const pagodaOffset = -((cam * 0.32) % 1380);
      let pagodaIndex = 0;
      for (let x = pagodaOffset + 160; x < W + 220; x += 1380) {
        const y = 132 + (pagodaIndex % 2) * 7;
        pagodaIndex++;
        fill(x - 62, y + 47, 92, 36, "#5f6972");
        fill(x - 46, y + 35, 78, 18, "#7a8790");
        fill(x - 46, y + 10, 26, 48, "#5b8356");
        fill(x - 24, y + 0, 31, 56, "#6b925f");
        fill(x - 59, y + 28, 16, 23, "#e69fb8");
        fill(x - 44, y + 22, 22, 22, "#f5bdd1");
        fill(x - 10, y, 42, 10, "#394054");
        fill(x - 6, y + 10, 34, 12, "#66516a");
        fill(x - 14, y + 22, 50, 9, "#394054");
        fill(x - 8, y + 31, 38, 12, "#66516a");
        fill(x - 18, y + 43, 58, 8, "#394054");
        fill(x - 8, y + 3, 4, 42, "#22242a");
        fill(x + 8, y + 3, 4, 42, "#22242a");
        fill(x + 22, y + 3, 4, 42, "#22242a");
        fill(x + 8, y - 12, 4, 12, "#c9e4f1");
      }
      const bridgeOffset = -((cam * 0.42) % 1380);
      let bridgeIndex = 0;
      for (let x = bridgeOffset + 650; x < W + 220; x += 1380) {
        const y = 226 + (bridgeIndex % 2) * 4;
        bridgeIndex++;
        fill(x - 58, y, 138, 6, "#cf6d6e");
        fill(x - 58, y + 6, 138, 2, "#924849");
        for (let p = 0; p < 7; p++) fill(x - 52 + p * 21, y + 8, 4, 19, "#bf5d60");
      }
    }
    function drawTrees(cam) {
      const offset = -((cam * 0.53) % 130);
      for (let x = offset - 150; x < W + 150; x += 130) {
        fill(x, 192, 5, 60, "#3f362d");
        fill(x - 18, 172, 42, 18, "#66895f");
        fill(x - 25, 187, 56, 22, "#587a52");
      }
      const cherryOffset = -((cam * 0.48) % 220);
      for (let x = cherryOffset - 240; x < W + 200; x += 220) {
        fill(x, 204, 4, 48, "#58483c");
        fill(x - 20, 180, 42, 18, "#eba7bf");
        fill(x - 16, 196, 32, 14, "#f5c1d5");
      }
    }
    function drawRoad(cam) {
      drawProceduralRoad(cam);
    }
    
function drawRealmLightingOverlay() {
      return;
    }


    
function drawBackground(cam) {
      const m = distanceMetres();

      // 0-1km: Forest backdrop.
      // Around 1km: fade into Logging Pass image layers.
      const loggingIn = clamp((m - 940) / 120, 0, 1);

      // Around 2km: fade from Logging Pass into Cinder Path backdrop.
      const cinderIn = clamp((m - 1940) / 140, 0, 1);

      // Around 3km: fade from Cinder Path into the final Mystic Sakura Forest.
      const sakuraIn = clamp((m - 2940) / 140, 0, 1);

      const forestAlpha = clamp(1 - loggingIn, 0, 1);
      const loggingAlpha = clamp(loggingIn * (1 - cinderIn), 0, 1);
      const cinderAlpha = clamp(cinderIn * (1 - sakuraIn), 0, 1);
      const sakuraAlpha = clamp(sakuraIn, 0, 1);

      if (forestAlpha > 0.001) drawForestBackdrop(cam, forestAlpha);
      if (loggingAlpha > 0.001) drawLoggingPassBackdrop(cam, loggingAlpha);
      if (cinderAlpha > 0.001) drawCinderBackdrop(cam, cinderAlpha);
      if (sakuraAlpha > 0.001) drawMysticSakuraBackdrop(cam, sakuraAlpha);

      drawScorchedBackgroundEffects(cam);
      drawRoad(cam);
      drawRealmLightingOverlay();
    }


    function getCurrentPlayerAnim() {
      const busyAction = player.actionTimer > 0 ? player.actionName : "";
      const moving = Math.abs(player.vx) + Math.abs(player.vy) > 0.16;
      const sprinting = player.grounded && sprintDir !== 0 && Math.abs(player.vx) > 2.0;

      if (player.dead) return PLAYER_ANIMS.death;
      if (player.hurtTimer > 0) return PLAYER_ANIMS.hurt;
      if (busyAction) return PLAYER_ANIMS[busyAction];
      if (player.block) return PLAYER_ANIMS.defend;
      if (player.jumpStartTimer > 0) return PLAYER_ANIMS.jumpStart;
      if (player.jumpTransitionTimer > 0) return PLAYER_ANIMS.jumpTransition;
      if (!player.grounded && player.vz > 0.75) return PLAYER_ANIMS.jump;
      if (!player.grounded) return PLAYER_ANIMS.jumpFall;
      if (moving && sprinting) return PLAYER_ANIMS.run;
      if (moving) return PLAYER_ANIMS.walk;
      return PLAYER_ANIMS.idle;
    }

    function getPlayerFrame(anim) {
      // Defend atlas rule:
      // frame 1 = holding block, frames 2-4 = successful block sparks,
      // frames 5-6 = idle holding block variation.
      if (anim === PLAYER_ANIMS.defend) {
        if (player.blockSparkTimer > 0) {
          const sparkFrames = [1, 2, 3]; // zero-based: atlas frames 2,3,4
          const elapsed = player.blockSparkTotal - player.blockSparkTimer;
          return sparkFrames[Math.min(2, Math.floor(elapsed / (player.blockSparkTotal / 3)))];
        }
        const holdFrames = [0, 4, 5]; // zero-based: atlas frames 1,5,6
        return holdFrames[Math.floor(performance.now() / 260) % holdFrames.length];
      }

      if (player.dead) {
        const elapsed = player.actionTotal - player.actionTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (player.hurtTimer > 0) {
        const elapsed = player.hurtTotal - player.hurtTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (player.actionTimer > 0 && PLAYER_ANIMS[player.actionName] === anim) {
        const elapsed = player.actionTotal - player.actionTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / player.actionFrameMs)));
      }
      if (player.jumpStartTimer > 0 && anim === PLAYER_ANIMS.jumpStart) {
        const total = player.jumpStartTotal;
        const elapsed = total - player.jumpStartTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (player.jumpTransitionTimer > 0 && anim === PLAYER_ANIMS.jumpTransition) {
        const total = player.jumpTransitionTotal;
        const elapsed = total - player.jumpTransitionTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (anim === PLAYER_ANIMS.walk || anim === PLAYER_ANIMS.run) {
        return Math.floor(player.walkClock * anim.fps) % anim.frames;
      }
      if (anim.loop) return Math.floor(performance.now() / (1000 / anim.fps)) % anim.frames;
      return 0;
    }

    function drawPlayer(cam) {
      if (player.dead && player.actionName === "death" && player.actionTimer <= 0) return;

      const altAnim = getPlayer1VisualAnim();
      if (altAnim) {
        const frame = getPlayer2Frame(altAnim);
        const px = sx(player.x, cam);
        const py = player.roadY - player.z;

        ctx.save();
        ctx.translate(Math.round(px), Math.round(py));
        if (player.facing < 0) ctx.scale(-1, 1);

        const shadowW = Math.max(24, 42 - player.z * 0.5);
        shadowOval(0, -2, shadowW, 7, 0.13);

        if (player.invulnTimer > 0 && Math.floor(player.invulnTimer / 60) % 2 === 0) ctx.globalAlpha = 0.75;
        if (player.dead && player.actionName === "death" && player.actionTimer < 260 && Math.floor(player.actionTimer / 45) % 2 === 0) ctx.globalAlpha = 0.35;

        const srcX = altAnim.frameXs ? altAnim.frameXs[frame] : frame * PLAYER2_FRAME_W;
        const srcW = altAnim.frameWs ? altAnim.frameWs[frame] : PLAYER2_FRAME_W;
        ctx.drawImage(
          altAnim.img,
          srcX, 0, srcW, altAnim.fh || PLAYER2_FRAME_H,
          -Math.round(PLAYER2_BODY_PIVOT_X * PLAYER2_SCALE),
          -Math.round(PLAYER2_FEET_Y * PLAYER2_SCALE),
          (altAnim.dw || PLAYER2_FRAME_W) * PLAYER2_SCALE,
          (altAnim.dh || PLAYER2_FRAME_H) * PLAYER2_SCALE
        );

        ctx.restore();
        return;
      }

      const anim = getCurrentPlayerAnim();
      const frame = getPlayerFrame(anim);
      const px = sx(player.x, cam);
      const py = player.roadY - player.z;

      ctx.save();
      ctx.translate(Math.round(px), Math.round(py));
      if (player.facing < 0) ctx.scale(-1, 1);

      const shadowW = Math.max(24, 46 - player.z * 0.5);
      shadowOval(0, -2, shadowW, 7, 0.13);

      if (player.invulnTimer > 0 && Math.floor(player.invulnTimer / 60) % 2 === 0) ctx.globalAlpha = 0.75;
      if (player.dead && player.actionName === "death" && player.actionTimer < 260 && Math.floor(player.actionTimer / 45) % 2 === 0) ctx.globalAlpha = 0.35;

      ctx.drawImage(
        anim.img,
        frame * FRAME_W, 0, FRAME_W, FRAME_H,
        -Math.round(PLAYER_BODY_PIVOT_X * PLAYER_SCALE),
        -Math.round(PLAYER_FEET_Y * PLAYER_SCALE),
        FRAME_W * PLAYER_SCALE,
        FRAME_H * PLAYER_SCALE
      );

      ctx.globalAlpha = 1;
      ctx.restore();
    }


    function getCurrentPlayer2Anim() {
      const busyAction = player2.actionTimer > 0 ? player2.actionName : "";
      const moving = Math.abs(player2.vx) + Math.abs(player2.vy) > 0.16;

      if (player2.dead) return PLAYER2_ANIMS.death;
      if (player2.hurtTimer > 0) return PLAYER2_ANIMS.hurt;
      if (busyAction) return PLAYER2_ANIMS[busyAction] || PLAYER2_ANIMS.idle;
      if (player2.block) return PLAYER2_ANIMS.defend;
      if (!player2.grounded) return PLAYER2_ANIMS.jump;
      if (moving) return PLAYER2_ANIMS.run;
      return PLAYER2_ANIMS.idle;
    }

    function getPlayer2Frame(anim) {
      if (anim === PLAYER2_ANIMS.defend) {
        if (player2.blockSparkTimer > 0) {
          const sparkFrames = [1, 2, 3];
          const elapsed = player2.blockSparkTotal - player2.blockSparkTimer;
          return sparkFrames[Math.min(2, Math.floor(elapsed / (player2.blockSparkTotal / 3)))];
        }
        const holdFrames = [0, 4, 5];
        return holdFrames[Math.floor(performance.now() / 260) % holdFrames.length];
      }
      if (player2.dead) {
        const elapsed = player2.actionTotal - player2.actionTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (player2.hurtTimer > 0) {
        const elapsed = player2.hurtTotal - player2.hurtTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps))));
      }
      if (player2.actionTimer > 0 && PLAYER2_ANIMS[player2.actionName] === anim) {
        const elapsed = player2.actionTotal - player2.actionTimer;
        return Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / player2.actionFrameMs)));
      }
      if (anim === PLAYER2_ANIMS.run) {
        const sprinting = player2SprintTimer > 0 && player2SprintDir !== 0 && Math.abs(player2.vx) > 2.05;
        // Normal run is deliberately slow; sprint cycles closer to the old run speed.
        const speedScale = sprinting ? 0.85 : 0.28;
        return Math.floor(player2.walkClock * anim.fps * speedScale) % anim.frames;
      }
      if (anim.loop) return Math.floor(performance.now() / (1000 / anim.fps)) % anim.frames;
      return 0;
    }

    function drawPlayer2(cam) {
      if (!player2.active) return;
      if (player2.dead && player2.actionName === "death" && player2.actionTimer <= 0) return;
      const anim = getCurrentPlayer2Anim();
      const frame = getPlayer2Frame(anim);
      const px = sx(player2.x, cam);
      const py = player2.roadY - player2.z;
      if (px < -220 || px > W + 220) return;

      ctx.save();
      ctx.translate(Math.round(px), Math.round(py));
      if (player2.facing < 0) ctx.scale(-1, 1);

      const shadowW = Math.max(24, 42 - player2.z * 0.5);
      shadowOval(0, -2, shadowW, 7, 0.12);

      if (player2.invulnTimer > 0 && Math.floor(player2.invulnTimer / 60) % 2 === 0) ctx.globalAlpha = 0.75;
      if (player2.dead && player2.actionName === "death" && player2.actionTimer < 260 && Math.floor(player2.actionTimer / 45) % 2 === 0) ctx.globalAlpha = 0.35;

      const srcX = anim.frameXs ? anim.frameXs[frame] : frame * PLAYER2_FRAME_W;
      const srcW = anim.frameWs ? anim.frameWs[frame] : PLAYER2_FRAME_W;
      const srcH = anim.fh || PLAYER2_FRAME_H;
      const dstW = (anim.dw || PLAYER2_FRAME_W) * PLAYER2_SCALE;
      const dstH = (anim.dh || PLAYER2_FRAME_H) * PLAYER2_SCALE;

      ctx.drawImage(
        anim.img,
        srcX, 0, srcW, srcH,
        -Math.round(PLAYER2_BODY_PIVOT_X * PLAYER2_SCALE),
        -Math.round(PLAYER2_FEET_Y * PLAYER2_SCALE),
        Math.round(dstW),
        Math.round(dstH)
      );

      ctx.globalAlpha = 1;
      ctx.restore();
    }

    function archerAnimAndFrame(enemy) {
      if (enemy.dead) {
        const anim = ARCHER_ANIMS.death;
        const total = anim.frames * (1000 / anim.fps);
        const elapsed = total - Math.max(0, enemy.deathTimer - 450);
        return { anim, frame: Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps)))) };
      }

      if (enemy.hurtTimer > 0 || enemy.stunTimer > 0) {
        const anim = ARCHER_ANIMS.hurt;
        const total = anim.frames * (1000 / anim.fps);
        const elapsed = total - Math.max(0, enemy.hurtTimer || enemy.stunTimer);
        return { anim, frame: Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / (1000 / anim.fps)))) };
      }

      if (enemy.attackTimer > 0) {
        const anim = ARCHER_ANIMS[enemy.attackName] || ARCHER_ANIMS.attack;
        const elapsed = enemy.attackTotal - enemy.attackTimer;
        return { anim, frame: Math.min(anim.frames - 1, Math.max(0, Math.floor(elapsed / enemy.attackFrameMs))) };
      }

      if (enemy.defendTimer > 0) {
        const anim = ARCHER_ANIMS.block;

        // Shashu BLOCK.png frame meaning:
        // frame 0, 4, 5 = holding block
        // frame 1, 2, 3 = successful block / sparks
        if (enemy.defendFlashTimer > 0) {
          const elapsed = 210 - enemy.defendFlashTimer;
          const hitFrames = [1, 2, 3];
          return { anim, frame: hitFrames[Math.min(hitFrames.length - 1, Math.floor(elapsed / 70))] };
        }

        const holdFrames = [0, 4, 5];
        return { anim, frame: holdFrames[Math.floor((performance.now() + enemy.walkSeed) / 240) % holdFrames.length] };
      }

      if (!enemy.grounded || enemy.z > 0) {
        const anim = ARCHER_ANIMS.jump;
        const frame = Math.floor(performance.now() / (1000 / anim.fps)) % anim.frames;
        return { anim, frame };
      }

      const speed = Math.abs(enemy.vx) + Math.abs(enemy.vy);
      if (speed > 0.16) {
        const anim = ARCHER_ANIMS.run;
        const frame = Math.floor((performance.now() + enemy.walkSeed) / (1000 / anim.fps)) % anim.frames;
        return { anim, frame };
      }

      const anim = ARCHER_ANIMS.idle;
      const frame = Math.floor((performance.now() + enemy.walkSeed) / (1000 / anim.fps)) % anim.frames;
      return { anim, frame };
    }

