    function drawMysticSakuraPropCastShadow(def, x, y, scaleMul = 1, alpha = 1, flip = false, stretch = 1.75, skew = -0.24) {
      if (!def || !def.img || !def.img.complete || def.img.naturalWidth === 0 || alpha <= 0.001) return;

      const scale = def.scale * scaleMul;
      const dw = Math.round(def.bw * scale);
      const dh = Math.round(def.bh * scale);
      const shadowAlpha = Math.min(0.62, Math.max(0, alpha));

      ctx.save();
      ctx.translate(Math.round(x), Math.round(y + 2));

      // Flip vertically from the road-top anchor and skew down the road so the
      // top-edge prop appears to cast a long moon shadow over the playable road.
      ctx.transform(flip ? -1 : 1, 0, skew, -stretch, 0, 0);

      ctx.globalAlpha = shadowAlpha;
      ctx.filter = "brightness(0) blur(3px)";
      ctx.drawImage(
        def.img,
        def.x, def.y, def.bw, def.bh,
        -Math.round(dw / 2), -dh,
        dw, dh
      );

      // A second, softer longer pass gives the shadow a feathered edge.
      ctx.globalAlpha = shadowAlpha * 0.34;
      ctx.filter = "brightness(0) blur(8px)";
      ctx.drawImage(
        def.img,
        def.x, def.y, def.bw, def.bh,
        -Math.round(dw / 2), -dh,
        dw, dh
      );

      ctx.filter = "none";
      ctx.restore();
    }

    function drawTopMysticPropMoonShadows(cam) {
      const moonAlpha = moonRealmBlend();
      if (moonAlpha <= 0.001) return;

      const spacing = 92;
      const start = Math.floor(cam / spacing) - 4;
      const end = Math.floor((cam + W) / spacing) + 5;

      const topSmall = ["bush1", "bush2", "rock1", "rock2", "rock3", "rock4"];
      const feature = ["house", "gate", "lamp", "statue"];
      const topTrees = ["tree1", "tree2", "tree3", "tree4"];

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, ROAD_TOP - 2, W, H - ROAD_TOP + 8);
      ctx.clip();

      for (let i = start; i <= end; i++) {
        const baseWorldX = i * spacing;
        if (!isMysticSakuraWorldX(baseWorldX)) continue;

        const b = sakuraBlendForWorldX(baseWorldX);
        if (b <= 0.02) continue;

        const worldX = baseWorldX + Math.floor((hash2D(i, 0, 9601) - 0.5) * 38);
        const x = sx(worldX, cam);
        const flip = hash2D(i, 0, 9602) > 0.5;
        const featureRoll = hash2D(i, 0, 9603);

        let name;
        let scaleMul = 1.12 + hash2D(i, 0, 9604) * 0.30;
        let y = ROAD_TOP + 2 + Math.floor((hash2D(i, 0, 9605) - 0.5) * 3);

        // Tree shadows are the strongest and read like moonlight breaking through canopy.
        if (hash2D(i, 0, 9630) > 0.69) {
          const tname = topTrees[Math.floor(hash2D(i, 0, 9631) * topTrees.length)];
          const tx = x + Math.floor((hash2D(i, 0, 9633) - 0.5) * 18);
          const ty = ROAD_TOP + 1;
          const tscale = 0.82 + hash2D(i, 0, 9632) * 0.18;
          drawMysticSakuraPropCastShadow(
            mysticTreeByName(tname),
            tx,
            ty,
            tscale,
            moonAlpha * b * 0.60,
            hash2D(i, 0, 9634) > 0.5,
            2.15,
            -0.30
          );
        }

        if (featureRoll > 0.90) {
          name = feature[Math.floor(hash2D(i, 0, 9606) * feature.length)];
          if (name === "house") scaleMul = 1.36 + hash2D(i, 0, 9607) * 0.20;
          else if (name === "gate") scaleMul = 1.20 + hash2D(i, 0, 9608) * 0.20;
          else if (name === "lamp") scaleMul = 1.02 + hash2D(i, 0, 9609) * 0.22;
          else if (name === "statue") scaleMul = 1.04 + hash2D(i, 0, 9610) * 0.20;
        } else {
          if (featureRoll < 0.18) continue;
          name = topSmall[Math.floor(hash2D(i, 0, 9611) * topSmall.length)];
        }

        drawMysticSakuraPropCastShadow(
          mysticPropByName(name),
          x,
          y,
          scaleMul,
          moonAlpha * b * 0.46,
          flip,
          name === "house" || name === "gate" ? 1.90 : 1.55,
          -0.26
        );

        // Occasional second small prop shadow, matching the actual top-edge prop generation.
        if (featureRoll <= 0.90 && hash2D(i, 0, 9612) > 0.56) {
          const name2 = topSmall[Math.floor(hash2D(i, 0, 9613) * topSmall.length)];
          drawMysticSakuraPropCastShadow(
            mysticPropByName(name2),
            x + Math.floor((hash2D(i, 0, 9614) - 0.5) * 44),
            y + Math.floor((hash2D(i, 0, 9615) - 0.5) * 5),
            0.88 + hash2D(i, 0, 9616) * 0.24,
            moonAlpha * b * 0.36,
            hash2D(i, 0, 9617) > 0.5,
            1.42,
            -0.24
          );
        }
      }

      ctx.restore();
    }

    function drawMoonlitCanopyShadowOverlay(cam) {
      const moonAlpha = moonRealmBlend();
      if (moonAlpha <= 0.001) return;

      // First make the whole moon zone darker and colder.
      ctx.save();
      ctx.globalAlpha = moonAlpha;
      const shade = ctx.createLinearGradient(0, 0, 0, H);
      shade.addColorStop(0, "rgba(1,5,22,0.24)");
      shade.addColorStop(0.42, "rgba(1,5,22,0.38)");
      shade.addColorStop(1, "rgba(0,2,12,0.56)");
      ctx.fillStyle = shade;
      ctx.fillRect(0, 0, W, H);
      ctx.restore();

      // Soft moonlight from above the road. This is not a single big beam now:
      // it is a general wash which the prop shadows break up.
      ctx.save();
      ctx.globalAlpha = moonAlpha * 0.23;
      const wash = ctx.createLinearGradient(0, ROAD_TOP - 16, 0, ROAD_BOTTOM + 70);
      wash.addColorStop(0, "rgba(200,222,255,0.44)");
      wash.addColorStop(0.34, "rgba(160,195,255,0.18)");
      wash.addColorStop(1, "rgba(120,150,220,0.04)");
      ctx.fillStyle = wash;
      ctx.fillRect(0, ROAD_TOP - 20, W, H - ROAD_TOP + 20);
      ctx.restore();

      // Then cast mirrored versions of the top-road props/trees downward over the road,
      // creating the "moonlight breaking through trees" effect.
      drawTopMysticPropMoonShadows(cam);

    }

