    function finalDistanceReached() {
      const p1Dist = Math.max(player.deathDistance || 0, metresAtWorldX(player.x || START_X));
      const p2Dist = player2.active ? Math.max(player2.deathDistance || 0, metresAtWorldX(player2.x || START_X)) : 0;
      return Math.max(runBestDistance, p1Dist, p2Dist);
    }

