    let last = performance.now();
    function loop(now) {
      const dt = Math.min(32, now - last);
      last = now;
      worldAnimTime = now;

      // Reassert pixel-art rendering each frame.
      ctx.imageSmoothingEnabled = false;

      if (gameState === "paused") {
        if (wasPressed("escape")) {
          resumeGame();
          mouse.justLeft = false;
          mouse.justMiddle = false;
          justPressed.clear();
          justPressedCodes.clear();
          requestAnimationFrame(loop);
          return;
        }
        updateMenuMusic(dt);
        drawPauseOverlay();
        mouse.justLeft = false;
        mouse.justMiddle = false;
        justPressed.clear();
        justPressedCodes.clear();
        requestAnimationFrame(loop);
        return;
      }

      if (gameState !== "playing") {
        updateMenuMusic(dt);
        drawMenuScreen(dt);
        mouse.justLeft = false;
        mouse.justMiddle = false;
        justPressed.clear();
        justPressedCodes.clear();
        requestAnimationFrame(loop);
        return;
      }

      if (wasPressed("escape")) {
        pauseGame();
        drawPauseOverlay();
        mouse.justLeft = false;
        mouse.justMiddle = false;
        justPressed.clear();
        justPressedCodes.clear();
        requestAnimationFrame(loop);
        return;
      }

      // Let Grandfather join even when starting the run as Granddaughter,
      // because updatePlayer() exits early while Player 1 is inactive/dead.
      if (wasPressed("enter") && selectedPlayer1Character === "granddaughter") {
        joinGrandfatherWhenGranddaughterStarted();
      }

      updatePlayer(dt);
      updatePlayer2(dt);
      updateFootstepSfx(dt);
      updateEnemies(dt);
      updateExecutionerShadow(dt);
      updateOniShadow(dt);
      updateRollingLogs(dt);
      resolveBodyCollisions();
      updateSushiDrops(dt);
      updateRunBestDistance();
      updateCamera(dt);
      updateMp3StageMusic(dt);

      // Clear one-frame inputs only after BOTH players have read them.
      mouse.justLeft = false;
      mouse.justMiddle = false;
      justPressed.clear();
      justPressedCodes.clear();

      // Ronin sprite test is disabled now that Ronin is back inside the enemy system.
      // updateRoninTest(dt);

      const cam = cameraX();
      drawBackground(cam);
      drawExecutionerShadow(cam);
      drawOniShadow(cam);
      drawSushiDrops(cam);

      const drawables = enemies.map(e => ({ type: "enemy", y: e.roadY, ref: e }));
      drawables.push({ type: "player1", y: player.roadY, ref: player });
      if (player2.active) drawables.push({ type: "player2", y: player2.roadY, ref: player2 });

      // Rolling logs are physical road objects, so sort them by roadY with players/enemies.
      // Higher on the road = drawn behind. Lower on the road = drawn in front.
      for (const log of rollingLogs) {
        drawables.push({ type: "rollingLog", y: log.roadY, ref: log });
      }

      // Standalone Ronin sprite test disabled; real Ronin is now drawn through enemies.
      drawables.sort((a, b) => a.y - b.y);
      for (const d of drawables) {
        if (d.type === "enemy") drawEnemy(d.ref, cam);
        else if (d.type === "player2") drawPlayer2(cam);
        else if (d.type === "rollingLog") drawRollingLog(d.ref, cam);
        else drawPlayer(cam);
      }

      drawArrows(cam);
      drawShurikens(cam);
      drawDustBursts(cam);

      // Foreground layer: these props intentionally sit in front of the combatants.
      // This makes the player/enemies appear to move behind shrubs, rocks and debris
      // at the very bottom edge of the road.
      drawRoadEdgeProps(cam, 1);
      drawMysticSakuraRoadProps(cam, 1);
      drawScorchedSmokePropLayer(cam, 1);
      drawRoadTrees(cam, 1);

      drawWindDebrisLayer(cam);
      drawMoonlitCanopyShadowOverlay(cam);
      drawRealmTitle();
      drawHUD();
      drawDepthMarker();
      drawDeathOverlay();
      requestAnimationFrame(loop);
    }


    // ===== v111 Cinder Path fire/smoke asset integration =====
    const CINDER_HAZE_SMOKE_DEFS = [{"name": "Smoke 1", "url": "data:image/png;base64,", "frameW": 64, "frameH": 128, "frames": 14}, {"name": "Smoke 2", "url": "data:image/png;base64,", "frameW": 32, "frameH": 96, "frames": 14}, {"name": "Smoke 3", "url": "data:image/png;base64,", "frameW": 64, "frameH": 144, "frames": 14}, {"name": "Smoke 4", "url": "data:image/png;base64,", "frameW": 64, "frameH": 128, "frames": 14}, {"name": "Smoke 5", "url": "data:image/png;base64,", "frameW": 48, "frameH": 112, "frames": 14}].map(d => ({ ...d, img: loadImage(d.url) }));
