    function drawStripBottom(sheet, frameIndex, x, y, scale = 1, alpha = 1, flip = false) {
      if (!sheet || !sheet.img || !sheet.img.complete) return;
      const fx = ((frameIndex % sheet.frames) + sheet.frames) % sheet.frames;
      const dw = Math.round(sheet.frameW * scale);
      const dh = Math.round(sheet.frameH * scale);
      ctx.save();
      ctx.translate(Math.round(x), Math.round(y));
      ctx.globalAlpha = alpha;
      if (flip) ctx.scale(-1, 1);
      const oldSmooth = ctx.imageSmoothingEnabled;
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(
        sheet.img,
        fx * sheet.frameW, 0, sheet.frameW, sheet.frameH,
        -Math.round(dw / 2), -dh,
        dw, dh
      );
      ctx.imageSmoothingEnabled = oldSmooth;
      ctx.restore();
    }

    function drawImageFrameBottom(frameObj, x, y, scale = 1, alpha = 1, flip = false) {
      if (!frameObj || !frameObj.img || !frameObj.img.complete) return;
      const dw = Math.round(frameObj.w * scale);
      const dh = Math.round(frameObj.h * scale);
      ctx.save();
      ctx.translate(Math.round(x), Math.round(y));
      ctx.globalAlpha = alpha;
      if (flip) ctx.scale(-1, 1);
      const oldSmooth = ctx.imageSmoothingEnabled;
      ctx.imageSmoothingEnabled = true;
      ctx.imageSmoothingQuality = "high";
      ctx.drawImage(frameObj.img, -Math.round(dw / 2), -dh, dw, dh);
      ctx.imageSmoothingEnabled = oldSmooth;
      ctx.restore();
    }

    function drawCinderFireBase(x, y, scale, alpha) {
      ctx.save();
      ctx.globalAlpha = alpha;
      ctx.fillStyle = "#140d0d";
      ctx.beginPath();
      ctx.ellipse(Math.round(x), Math.round(y + 1), Math.round(10 * scale), Math.round(4 * scale), 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = alpha * 0.45;
      ctx.fillStyle = "#361714";
      ctx.beginPath();
      ctx.ellipse(Math.round(x), Math.round(y), Math.round(13 * scale), Math.round(5 * scale), 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function drawScorchedBackgroundEffects(cam) {
      const b = scorchedBlend() * (1 - sakuraBlend());
      if (b <= 0.01) return;

      const horizonY = ROAD_TOP + 10;
      ctx.save();

      const smokeGrad = ctx.createLinearGradient(0, 0, 0, horizonY + 150);
      smokeGrad.addColorStop(0, `rgba(12,8,10,${0.34 * b})`);
      smokeGrad.addColorStop(0.40, `rgba(42,20,18,${0.26 * b})`);
      smokeGrad.addColorStop(1, `rgba(19,12,13,${0.46 * b})`);
      ctx.fillStyle = smokeGrad;
      ctx.fillRect(0, 0, W, horizonY + 170);

      const redTint = ctx.createLinearGradient(0, 0, 0, H);
      redTint.addColorStop(0, `rgba(95,32,20,${0.05 * b})`);
      redTint.addColorStop(0.55, `rgba(110,38,20,${0.10 * b})`);
      redTint.addColorStop(1, `rgba(50,18,16,${0.16 * b})`);
      ctx.fillStyle = redTint;
      ctx.fillRect(0, 0, W, H);

      // Smoky haze using the uploaded Pixel Fire Asset Pack 2 smokes.
      // Larger, more frequent and slightly more visible so the haze reads clearly.
      const spacing = 145;
      const start = Math.floor((cam * 0.82) / spacing) - 6;
      const end = Math.floor((cam * 0.82 + W) / spacing) + 7;
      for (let i = start; i <= end; i++) {
        const worldX = i * spacing + Math.floor((hash2D(i, 9102, 1) - 0.5) * 135);
        if (!isScorchedRoadWorldX(worldX + 240)) continue;
        if (hash2D(i, 9103, 2) < 0.30) continue;

        const smoke = CINDER_HAZE_SMOKE_DEFS[Math.floor(hash2D(i, 9104, 3) * CINDER_HAZE_SMOKE_DEFS.length) % CINDER_HAZE_SMOKE_DEFS.length];
        const fps = 2.8 + hash2D(i, 9105, 4) * 1.7;
        const frame = Math.floor((worldAnimTime * fps / 1000 + hash2D(i, 9106, 5) * smoke.frames)) % smoke.frames;
        const x = sx(worldX, cam * (0.78 + hash2D(i, 9107, 6) * 0.08));
        const y = ROAD_TOP + 18 + Math.floor((hash2D(i, 9108, 7) - 0.5) * 68);
        const scale = 1.20 + hash2D(i, 9109, 8) * 1.20;
        const alpha = (0.18 + hash2D(i, 9110, 9) * 0.18) * b;
        drawStripBottom(smoke, frame, x, y, scale, alpha, hash2D(i, 9111, 10) > 0.5);
      }

      // Grain / ash haze.
      for (let i = 0; i < 230; i++) {
        const px = (hash2D(i, 4520, 16) * W) | 0;
        const py = (hash2D(i, 4521, 17) * (ROAD_TOP + 105)) | 0;
        const sz = 1 + ((hash2D(i, 4522, 18) * 2) | 0);
        ctx.globalAlpha = (0.020 + hash2D(i, 4523, 19) * 0.035) * b;
        const ember = hash2D(i, 4524, 20) > 0.82;
        ctx.fillStyle = ember ? "#8f3d1f" : (hash2D(i, 4525, 21) > 0.55 ? "#3a2422" : "#24181a");
        ctx.fillRect(px, py, sz, sz);
      }

      ctx.restore();
    }

    function drawScorchedSmokePropLayer(cam, layer) {
      const b = scorchedBlend() * (1 - sakuraBlend());
      if (b <= 0.02) return;

      const spacing = layer === 0 ? 165 : 136;
      const start = Math.floor(cam / spacing) - 4;
      const end = Math.floor((cam + W) / spacing) + 5;

      for (let i = start; i <= end; i++) {
        const baseWorldX = i * spacing;
        if (!isScorchedRoadWorldX(baseWorldX)) continue;

        const appearChance = layer === 0 ? 0.58 : 0.58;
        if (hash2D(i, layer, 9200) > appearChance) continue;

        const worldX = baseWorldX + Math.floor((hash2D(i, layer, 9201) - 0.5) * (layer === 0 ? 60 : 70));
        const x = sx(worldX, cam);
        const fire = SAFE_CINDER_FIRE_DEFS[Math.floor(hash2D(i, layer, 9202) * SAFE_CINDER_FIRE_DEFS.length) % SAFE_CINDER_FIRE_DEFS.length];
        const smoke = CINDER_FIRE_SMOKE_DEFS[Math.floor(hash2D(i, layer, 9203) * CINDER_FIRE_SMOKE_DEFS.length) % CINDER_FIRE_SMOKE_DEFS.length];
        const stump = CINDER_FLAMING_STUMP_DEFS[0];
        const house = CINDER_HOUSE_FIRE_DEFS[Math.abs(Math.floor(i / 2) + layer) % CINDER_HOUSE_FIRE_DEFS.length];
        const box = CINDER_BOX_FIRE_FRAMES.length ? CINDER_BOX_FIRE_FRAMES[Math.abs(Math.floor(worldAnimTime / 90) + i + layer) % CINDER_BOX_FIRE_FRAMES.length] : null;
        const flip = hash2D(i, layer, 9204) > 0.5;

        const fireFps = 11.5 + hash2D(i, layer, 9205) * 3.0;
        const smokeFps = 5.2 + hash2D(i, layer, 9206) * 2.0;
        const fireFrame = Math.floor((worldAnimTime * fireFps / 1000 + hash2D(i, layer, 9207) * fire.frames)) % fire.frames;
        const smokeFrame = Math.floor((worldAnimTime * smokeFps / 1000 + hash2D(i, layer, 9208) * smoke.frames)) % smoke.frames;
        const stumpFrame = Math.floor((worldAnimTime * (8.0 + hash2D(i, layer, 9231) * 2.0) / 1000 + hash2D(i, layer, 9232) * stump.frames)) % stump.frames;
        const houseFrame = Math.floor((worldAnimTime * (8.6 + hash2D(i, layer, 9236) * 1.4) / 1000 + hash2D(i, layer, 9237) * house.frames)) % house.frames;

        const useHouse = layer === 0 && house && house.img && house.img.complete && hash2D(i, layer, 9235) > 0.84;
        const useBox = !useHouse && layer === 0 && box && box.img && box.img.complete && hash2D(i, layer, 9240) > 0.42;
        const useStump = !useHouse && !useBox && stump && stump.img && stump.img.complete && (layer === 0 ? hash2D(i, layer, 9233) > 0.77 : hash2D(i, layer, 9233) > 0.70);

        let y, fireScale, smokeScale, smokeAlpha, fireAlpha, stumpScale, houseScale, boxScale;
        if (layer === 0) {
          y = ROAD_TOP + 4 + Math.floor((hash2D(i, layer, 9209) - 0.5) * 8);
          fireScale = 1.55 + hash2D(i, layer, 9210) * 0.75;
          smokeScale = (0.48 + hash2D(i, layer, 9211) * 0.34) * 1.5;
          smokeAlpha = (0.22 + hash2D(i, layer, 9212) * 0.12) * b;
          fireAlpha = 0.96 * b;
          stumpScale = 0.95 + hash2D(i, layer, 9234) * 0.30;
          houseScale = (1.10 + hash2D(i, layer, 9238) * 0.19) * (house.scaleMul || 1.0);
          boxScale = 0.88 + hash2D(i, layer, 9241) * 0.28;
        } else {
          y = H + 38 + Math.floor((hash2D(i, layer, 9213) - 0.5) * 12);
          fireScale = 1.90 + hash2D(i, layer, 9214) * 1.05;
          smokeScale = (0.70 + hash2D(i, layer, 9215) * 0.46) * 1.5;
          smokeAlpha = (0.28 + hash2D(i, layer, 9216) * 0.14) * b;
          fireAlpha = 1.0 * b;
          stumpScale = 1.15 + hash2D(i, layer, 9234) * 0.42;
          houseScale = 1.21 * (house.scaleMul || 1.0);
          boxScale = 1.0;
        }

        if (useHouse) {
          const houseY = ROAD_TOP + 1 + Math.floor((hash2D(i, layer, 9239) - 0.5) * 4);
          drawStripBottom(house, houseFrame, x, houseY, houseScale, 0.99 * b, flip);

          // Extra burning boxes clustered around houses on the top edge of the road.
          if (CINDER_BOX_FIRE_FRAMES.length) {
            const boxA = CINDER_BOX_FIRE_FRAMES[Math.abs(Math.floor(worldAnimTime / 90) + i * 3) % CINDER_BOX_FIRE_FRAMES.length];
            const boxB = CINDER_BOX_FIRE_FRAMES[Math.abs(Math.floor(worldAnimTime / 90) + i * 5 + 7) % CINDER_BOX_FIRE_FRAMES.length];
            const side = hash2D(i, layer, 9244) > 0.5 ? 1 : -1;
            const boxY = ROAD_TOP + 2;
            const boxScaleA = 0.78 + hash2D(i, layer, 9245) * 0.18;
            const boxScaleB = 0.68 + hash2D(i, layer, 9246) * 0.16;
            drawImageFrameBottom(boxA, x + side * (58 + hash2D(i, layer, 9247) * 18), boxY, boxScaleA, 0.98 * b, !flip);
            if (hash2D(i, layer, 9248) > 0.35) {
              drawImageFrameBottom(boxB, x - side * (52 + hash2D(i, layer, 9249) * 20), boxY, boxScaleB, 0.94 * b, flip);
            }
          }
        } else if (useBox) {
          const boxY = ROAD_TOP + 2;
          drawImageFrameBottom(box, x, boxY, boxScale, 0.98 * b, flip);
        } else if (useStump) {
          drawStripBottom(stump, stumpFrame, x, y + (layer === 0 ? 4 : 8), stumpScale, 0.98 * b, flip);
          drawStripBottom(smoke, smokeFrame, x + Math.floor((hash2D(i, layer, 9217) - 0.5) * 10), y - (layer === 0 ? 6 : 8), smokeScale * 1.15, smokeAlpha * 0.95, flip);
          if (hash2D(i, layer, 9224) > 0.74) {
            const smoke2 = CINDER_FIRE_SMOKE_DEFS[Math.floor(hash2D(i, layer, 9225) * CINDER_FIRE_SMOKE_DEFS.length) % CINDER_FIRE_SMOKE_DEFS.length];
            const smokeFrame2 = Math.floor((worldAnimTime * (smokeFps * 0.84) / 1000 + hash2D(i, layer, 9226) * smoke2.frames)) % smoke2.frames;
            drawStripBottom(
              smoke2,
              smokeFrame2,
              x + Math.floor((hash2D(i, layer, 9227) - 0.5) * 14),
              y + Math.floor((hash2D(i, layer, 9228) - 0.5) * 6) - (layer === 0 ? 4 : 6),
              smokeScale * (0.88 + hash2D(i, layer, 9229) * 0.20),
              smokeAlpha * 0.60,
              hash2D(i, layer, 9230) > 0.5
            );
          }
        } else {
          drawCinderFireBase(x, y, fireScale * 0.72, 0.32 * b);
          drawStripBottom(smoke, smokeFrame, x + Math.floor((hash2D(i, layer, 9217) - 0.5) * 8), y - 2, smokeScale, smokeAlpha, flip);
          drawStripBottom(fire, fireFrame, x, y + 2, fireScale, fireAlpha, flip);

          if (hash2D(i, layer, 9224) > 0.72) {
            const smoke2 = CINDER_FIRE_SMOKE_DEFS[Math.floor(hash2D(i, layer, 9225) * CINDER_FIRE_SMOKE_DEFS.length) % CINDER_FIRE_SMOKE_DEFS.length];
            const smokeFrame2 = Math.floor((worldAnimTime * (smokeFps * 0.86) / 1000 + hash2D(i, layer, 9226) * smoke2.frames)) % smoke2.frames;
            drawStripBottom(
              smoke2,
              smokeFrame2,
              x + Math.floor((hash2D(i, layer, 9227) - 0.5) * 18),
              y + Math.floor((hash2D(i, layer, 9228) - 0.5) * 6),
              smokeScale * (0.78 + hash2D(i, layer, 9229) * 0.24),
              smokeAlpha * 0.72,
              hash2D(i, layer, 9230) > 0.5
            );
          }
        }
      }
    }

    window.addEventListener("load", seasonInit);
    requestAnimationFrame(loop);
  
